programs.sol:
"""Mostly a document-onset pulse, rather than a continuing text feature.

Estimate its size from the first token's familiar form: whitespace, numerals,
English function words, capitalization, and source-code opening conventions.
Keep the pulse while that first token repeats; otherwise return near zero.
The document end marker has an opposite pulse. These broad classes deliberately
ignore the many idiosyncratic differences between individual first tokens.
"""
import unicodedata

READS = ()
ARTICLES = {'a', 'an', 'the'}
PREPOSITIONS = set('of to in for on at by from with into onto over under '
                   'between without within through about after before during '
                   'as toward across against around until upon out'.split())
OPEN_QUESTIONS = {'what', 'why', 'how'}
OTHER_QUESTIONS = {'who', 'where', 'when', 'which'}


def onset(s):
    word = s.strip()
    spaced = s.startswith(' ')
    if s == '<|im_start|>':
        return 4.92
    if s == '<|endoftext|>':
        return 10.09
    if not word:
        return -0.4 if spaced else 4.2 if '\n' in s else 2.1
    if s == 'import':
        return 18.5
    if word == '0':
        return 10.2
    if word.isdecimal():
        return 0.16 if word == '1' else 2.5
    capital = word[0].isupper()
    lower = word.lower()
    if lower in ARTICLES:
        return (4.8 if spaced else 7.0) if capital else (4.9 if spaced else 5.5)
    if word == 'I':
        return 6.9 if spaced else 9.6
    if lower in PREPOSITIONS:
        return 0.1 if capital else 1.5
    if lower in OPEN_QUESTIONS:
        return 14.0 if capital and not spaced else 6.0
    if lower in OTHER_QUESTIONS:
        return 4.0 if capital and not spaced else 3.0
    if s.startswith(('//', '/*')):
        return 7.8
    if word in {',', '，', '、'}:
        return 0.3
    if unicodedata.category(word[0]) == 'Pd':
        return 0.2 if spaced else 1.0
    if all(unicodedata.category(c).startswith('P') for c in word):
        return 1.3 if spaced else 2.4
    if capital:
        return 3.3 if spaced else 4.1
    return 2.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, prefix.token_ids[-1], True)
    doc, first, repeating = carry
    repeating = repeating and prefix.token_ids[-1] == first
    if repeating:
        value = onset(token)
    elif token == '<|endoftext|>':
        value = -2.43
    else:
        value = -0.003
    return (doc, first, repeating), value

programs.haiku:
"""Explanation of layers.1.mlp.down_proj:2752 as a document-start detector.

The component is silent inside a document except at two kinds of token:
  * the first token of every document (or of a packed row): it fires, and its
    size depends on what the token is (see KIND_VALUE below);
  * the end-of-text token <|endoftext|>, which ends each document: a fixed dip.

Document-start size, by the kind of the first token:
  Indic-script letters (Devanagari, Bengali, Malayalam, ...)  -> strongest (~12)
  ALL-CAPS words                                             -> ~4.5
  Capitalised words (The, What, Hello)                       -> ~4.2
  digits                                                      -> ~3.5
  other words, CJK, other scripts                             -> ~2.8
  punctuation                                                 -> ~2.4
  whitespace only                                             -> ~1.2
"""
import unicodedata

READS = ()

END_OF_TEXT = "<|endoftext|>"
INDIC = ("DEVANAGARI", "BENGALI", "GURMUKHI", "GUJARATI", "ORIYA", "TAMIL",
         "TELUGU", "KANNADA", "MALAYALAM", "SINHALA")
END_VALUE = -2.4
KIND_VALUE = {"indic": 12.0, "allcaps": 4.5, "capital": 4.2, "digits": 3.5,
              "word": 2.8, "punct": 2.4, "space": 1.2}


def _script(ch):
    try:
        return unicodedata.name(ch).split()[0]
    except ValueError:
        return ""


def _kind(text):
    s = text.strip()
    if not s:
        return "space"
    scripts = [_script(ch) for ch in s]
    if any(name in INDIC for name in scripts):
        return "indic"
    if s.isdigit():
        return "digits"
    if not any(ch.isalnum() for ch in s):
        return "punct"
    if s.isalpha() and s.isupper() and len(s) >= 2:
        return "allcaps"
    if s[0].isupper():
        return "capital"
    return "word"


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] == END_OF_TEXT:
        return None, END_VALUE
    starts_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_doc:
        return None, 0.0
    return None, KIND_VALUE[_kind(prefix.token_strings[-1])]

programs.sol:
"""A pulse at document onset, sustained through an identical-token opening run.

The pulse is calibrated by visible token form: numbers, capitalization,
whitespace, ordinary words, and punctuation. Tight opening parentheses have
particularly large amplitudes. Once a different token arrives, predict zero;
the small later fluctuations and other context-dependent effects are omitted.
"""
import math
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

SUBJECT_PRONOUNS = set('i you he she we they'.split())
ARTICLES = set('a an the'.split())
AUXILIARIES = set(
    'am is are was were be been being have has had do does did '
    'can could will would shall should may might must'.split()
)
DECLARATIONS = set('package import using namespace from const export var'.split())
INTEGER_TYPES = set('int uint long short unsigned signed'.split())


def word_amplitude(text):
    word = text.strip()
    lower = word.lower()
    value = 3.87 - 0.93 * text[:1].isspace()
    value += 1.05 * word[:1].isupper()
    value -= 1.30 * (word.isupper() and len(word) > 1)
    value -= 0.59 * math.log1p(len(word))
    value += 0.12 * zipf_frequency(lower, 'en')
    value += 2.61 * (lower in SUBJECT_PRONOUNS)
    value += 0.64 * (lower in ARTICLES)
    value += 0.75 * (lower in AUXILIARIES)
    value -= 2.92 * (lower in DECLARATIONS)
    value += 1.31 * (lower in INTEGER_TYPES)
    value += 1.98 * (lower in {'no', 'not', 'never'})
    value += 1.94 * word.startswith(('_', '.', '#', '/'))
    value += 0.80 * (not word.isascii())
    return value


@lru_cache(maxsize=8192)
def opening_amplitude(text):
    word = text.strip()
    spaced = text[:1].isspace()
    if text.startswith('<|'):
        return 2.37
    if not word:
        if text == ' ':
            return -0.34
        if text == '  ':
            return 2.26
        if '\r' in text and '\n' not in text:
            return -1.7
        if '\n' in text:
            return (1.0 if text.startswith(' ') else
                    3.69 if text == '\n' else 2.29)
        if '\t' in text:
            return 6.3 if text.strip('\t') == '' else 4.5
        return 3.3 + math.log(max(1, len(text) / 3))
    if word.isdecimal():
        return 8.24 if word == '0' else 5.6
    if word.startswith('('):
        if spaced:
            return 5.8
        if any(c.isalpha() for c in word):
            return 23.5
        if word == '(':
            return 18.88
        return 13.5 if ')' in word else 11.0
    if any(c.isalpha() for c in word):
        return word_amplitude(text)
    if '\\' in word:
        return 12.0
    if word.startswith(('//', '/*')):
        return -0.4
    if word[0] in '\'"“”‘’':
        return -0.5
    if word.startswith('#'):
        return 1.0
    if '\n' in text:
        return 2.0 if '\n\n' in text else 5.5
    if word in {'.', ','}:
        return 9.4 if word == '.' and spaced else 2.8
    if word in {':', ';'}:
        return 0.8
    if word in {'-', '+'} and spaced:
        return 5.25
    if word == '|':
        return 3.5 if spaced else 1.2
    return 3.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first = token
        value = opening_amplitude(prefix.token_strings[-1])
    else:
        _, first, value = carry
        if token != first:
            value = 0.0  # Once the opening run ends, the pulse stays off.
    return (doc, first, value), value

programs.haiku:
"""Document-opening token detector for layers.1.mlp.down_proj:2754.

What the component does, in plain terms: it is almost silent everywhere except on the
FIRST token of a document (or of a row segment). There the token's own spelling decides
how strongly it fires. Roughly, from strongest to weakest:

  * an opening parenthesis glued to a word, "(null", "(final", "(handle": very strong
  * a code symbol glued to a word, ",NULL", "=True", ".class", "\\t", "[item": strong
  * null / boolean / void literals ("null", " nil", " None", " true", " void"): strong
  * a sentence-initial subject pronoun ("We", "I", "They", "He", "You"): fairly strong
  * digits and capitalised words: medium
  * plain lowercase words, non-ASCII words, and other punctuation: weak
  * comment markers ("//", "#", "/*") and quotes: near zero
  * whitespace-only tokens: weakest

Every other position predicts 0; its real values there are close to 0.

The first token of a document is recognised from the prefix alone: it is position 0 of
the row, or the document id changes at this token. Attention resets there, so the
activation depends only on that token, not on what came before.

The numbers are the average activation for each class over the training data's document
starts (weighted by how often each token starts a document). The program predicts the
class mean; it does not look up individual tokens.
"""

READS = ()

SUBJECT_PRONOUNS = {"I", "We", "They", "You", "He", "She"}
NULL_WORDS = {"null", "nil", "none", "nullptr", "true", "false", "void", "undefined", "nan"}


def _guess(token):
    """Predicted activation for a token that opens a document."""
    body = token.lstrip(" ")
    if not body.strip():
        return 2.0  # whitespace only
    first = body[0]
    after = body[1:2]  # the character after the first one
    word = "".join(ch for ch in token if ch.isalpha()).lower()
    if first == "(":
        return 23.5 if after.isalpha() else 9.0
    if word in NULL_WORDS:
        return 11.0
    if body in SUBJECT_PRONOUNS:
        return 8.0
    if "\\" in token:
        return 9.0
    if first in "/#":
        return 4.5 if after.isalpha() else 0.8  # comment or path markers: low
    if first == '"':
        return 1.5
    if first in ".,=[":
        return 7.0 if after.isalpha() else 3.0  # code symbol glued to a word: high
    if first.isdigit():
        return 5.9
    if not first.isascii():
        return 3.9
    if first.isalpha():
        if token.startswith(" "):
            return 2.9
        return 4.9 if first.isupper() else 3.0
    return 3.8 if token.startswith(" ") else 3.0  # other punctuation and symbols


def step(carry, prefix, upstream):
    position = prefix.position
    starts_document = position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, _guess(prefix.token_strings[-1])

"""Set-reference detector for layers.1.mlp.down_proj:2755.

The component fires on words that refer back to one member, or to the pair or trio, of a
small group just named: "the former", "the latter", "these two", "all three", "both of them",
"either of", "both are", "one of which", and their French, Spanish and Chinese equivalents.
It is near zero everywhere else, and slightly negative after nouns that take a complement
("the purpose of", "the goal of", "the trouble with"). Each kind of reference gets the
typical size of its activation. Context is the last three words of the same document."""

READS = ()

NUMBERS = {"two", "three", "four"}
DEMONSTRATIVES = {"these", "those", "all"}
DETERMINERS = {"the", "both", "of", "first", "other", "last", "this"}
PARTITIVE_HEADS = {"either", "neither", "both", "all", "each", "one", "any", "none", "some", "most", "many", "two", "three"}
PRONOUNS = {"them", "these", "those", "which", "whom"}
ORDINALS = {"first", "second", "third", "last", "following"}
REFERRERS = {"two", "three", "four", "former", "latter", "first", "second", "both", "these", "those"}
GROUP_SUBJECTS = {"these", "those", "all", "each", "either", "neither", "second", "other"}
# nouns whose complement follows: "the purpose of", "the strength of", "the thing about"
RELATIONAL_NOUNS = {
    "purpose", "purposes", "goal", "goals", "aim", "objective", "objectives", "intention",
    "strength", "problem", "trouble", "thing", "things", "point", "beauty", "advantage",
    "advantages", "benefit", "benefits", "essence", "power", "aspect", "aspects", "feature",
    "features", "challenge", "lesson", "issue", "focus",
}


def step(carry, prefix, upstream):
    # the last three words of the current document (a new document resets the context)
    words = []
    for i in range(1, 4):
        if len(prefix.document_ids) < i or prefix.document_ids[-i] != prefix.document_ids[-1]:
            break
        words.insert(0, prefix.token_strings[-i].strip().lower())
    cur = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    prev2 = words[-3] if len(words) > 2 else ""
    # Chinese 者 after 两/三/前/后 ("the two", "the former", "the latter")
    if "者" in cur and prev in ("后", "後", "前", "两", "兩", "三"):
        value = 8.0                      # Chinese "the latter", "the former", "the two"
    elif cur in ("former", "latter") and prev == "the":
        value = 6.0                      # "the former", "the latter"
    elif cur in NUMBERS and prev in DEMONSTRATIVES:
        value = 4.7                      # "these two", "all three"
    elif cur in NUMBERS and prev in DETERMINERS:
        value = 1.8                      # "the two", "both three"
    elif cur in PRONOUNS and prev == "of":
        value = 2.1 if prev2 in PARTITIVE_HEADS else 0.3   # "both of them", "of these"
    elif cur == "of" and prev in ("either", "neither"):
        value = 4.4                      # "either of"
    elif cur in ("are", "is", "were", "have") and prev == "both":
        value = 4.5                      # "both are"
    elif cur in ("are", "is", "were", "have") and prev in GROUP_SUBJECTS:
        value = 1.5                      # "these are", "all are", "each is"
    elif cur == "of" and prev in ("both", "first", "second", "each", "all"):
        value = 1.3                      # "both of", "the first of"
    elif cur in ("deux", "tres") and prev in ("les", "los", "las", "des"):
        value = 3.0                      # "les deux", "los tres"
    elif cur == "both":
        value = 0.5
    elif cur in ORDINALS and prev == "the":
        value = 0.6                      # "the second", "the following"
    elif prev in REFERRERS and prev2 in DETERMINERS | DEMONSTRATIVES:
        value = 0.6                      # the noun after "the two", "these first"
    elif cur in ("of", "about", "with") and prev in RELATIONAL_NOUNS:
        value = -0.8                     # "the purpose of", "the thing about"
    else:
        value = 0.0
    return carry, value

"""Opening-token negatives: a document in a packed row often starts partway through a sentence, so
the model has almost no context at its first few tokens. Its MLP output here is strongly negative on
the token right after an opening word cut off mid-sentence, when that token is punctuation or a
connecting word (',' '.' 'and' 'of' 'is' ...). Weaker negatives follow for punctuation later in the
document's opening, and the document's first token is slightly negative. Everywhere else it is ~0."""

READS = ()

FUNCTION_WORDS = set(
    "the a an of and or to in on at for with by from as is are was were be been that this it its "
    "which who what when where how but if so then than not no can will would should could may might "
    "do does did has have had he she they we you i his her their our your my me him them us there "
    "here about into over under also just more most very some any all each other such only".split()
)


def is_punct(s):
    """Punctuation or whitespace: a token with no letters or digits, such as ',' or '.)'."""
    return not any(c.isalnum() for c in s)


def is_mid_sentence_word(s):
    """A word cut off mid-sentence: 3+ letters, not a function word, and either lowercase (a word
    piece) or capitalised with a leading space. Sentence-initial words (no leading space) don't count."""
    w = s.strip()
    if len(w) < 3 or not w.isalpha() or w.lower() in FUNCTION_WORDS:
        return False
    return w.islower() or s[:1] == " "


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        pos, seen_punct, first = 0, False, tok
    else:
        pos, seen_punct, first = carry[1] + 1, carry[2], carry[3]
    value = 0.0
    if pos == 0:
        value = -0.2
    elif pos == 1:
        # The second token of the document, read against the opening word.
        opening_word = is_mid_sentence_word(first)
        if is_punct(tok):
            value = -4.5 if opening_word else -0.9
        elif tok.strip() in FUNCTION_WORDS:
            value = -2.5 if opening_word else -0.35
        elif opening_word:
            value = -0.7 if is_mid_sentence_word(tok) else -0.8
    elif pos >= 2 and is_punct(tok) and not seen_punct:
        # First punctuation mark of the document, fading with distance from the start.
        value = -0.65 * 0.8 ** (pos - 2)
    if is_punct(tok):
        seen_punct = True
    return (doc, pos, seen_punct, first), value

programs.sol:
"""Usefulness, applicability, and the prepositions connecting things to roles.

Add learned responses for recognizable word classes. On a preposition,
look for those concepts in the preceding five words, with distance decay.
WordNet recognizes English inflections; word endings and forms of be modify
responses. This is a local lexical approximation, not a semantic parser.
Documents, newlines, and .!?; clear the recent words.
This English-focused approximation omits most remaining activation variation.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Concept: (dictionary roots, current-word response, next-preposition
# response, response to a nearby but non-adjacent preposition).
CONCEPTS = {
    'use': ('use utilize', -0.0849, -0.5373, -0.4713),
    'application': ('apply applicable application', -0.079, -0.7308, -0.4346),
    'suitability': (
        'useful helpful suitable suited appropriate ideal beneficial '
        'advantageous effective efficient desirable practical convenient '
        'versatile compatible disadvantageous ineffective unsuitable',
        -0.2074, -0.8193, -0.4137,
    ),
    'praise': (
        'good great excellent wonderful fine nice valuable invaluable '
        'perfect popular famous',
        -0.1569, -0.3432, -0.2072,
    ),
    'importance': (
        'important essential crucial vital significant critical '
        'fundamental indispensable',
        -0.0734, -0.2117, -0.4877,
    ),
    'location': ('locate situate', -0.0028, -0.3286, -0.0183),
    'role': ('role addition', -0.1253, -0.2092, -0.3502),
    'part_whole': ('part component element', -0.0439, 0.0314, 0.0553),
    'effect': (
        'effect affect impact influence contribution factor',
        -0.1051, -0.1112, -0.2113,
    ),
    'emphasis': ('especially particularly', 0.0322, -0.3928, -0.5042),
    'intensity': (
        'widely commonly frequently extensively broadly increasingly '
        'mainly primarily highly very',
        -0.0416, -0.2114, -0.6059,
    ),
}

WORD_MODIFIERS = {
    'use': {'ed': -0.3301, 'be': -0.3953, 'emphasis': -0.3366},
    'application': {'s': -0.6549},
    'suitability': {'be': -0.3723, 'emphasis': -0.2501},
}

LINK_MODIFIERS = {
    'use': {'be': -0.5226, 'in': -0.5603, 'of': 0.4003},
    'application': {'of': 0.5223},
    'suitability': {'be': -0.518, 'for': -0.538, 'to': 0.4593},
    'praise': {'for': -0.7764},
    'location': {'ed': -0.3286, 'in': -0.461},
    'role': {'in': -0.487},
    'part_whole': {'be': -0.4166, 'of': -0.3923},
    'effect': {'on': -0.7194},
    'emphasis': {'in': -0.5174},
}

PREPOSITIONS = {
    'in': -0.0975,
    'for': -0.0644,
    'to': -0.0228,
    'on': -0.0248,
    'of': 0.0187,
    'as': -0.0356,
    'at': 0.0115,
    'by': -0.0378,
    'with': -0.0042,
    'from': 0.0042,
    'into': -0.0431,
    'when': -0.0451,
}

ROOTS = {g: frozenset(rule[0].split()) for g, rule in CONCEPTS.items()}
BE_FORMS = frozenset('be is are was were been being'.split())

@lru_cache(maxsize=32768)
def word_classes(word):
    bases = {word}
    if word.isascii() and word.isalpha():
        bases.update(wordnet.base_forms(word))
    return frozenset(g for g, roots in ROOTS.items() if bases & roots)

def advance(history, token):
    # Preserve word pieces but forget context at punctuation and line boundaries.
    if '\n' in token:
        return re.findall(r"[\w'-]+", token.rsplit('\n', 1)[-1].lower())[-5:]
    if any(c in token for c in '.!?;'):
        history = []
    if token and (token[0].isspace() or not history):
        history = history + re.findall(r"[\w'-]+", token.lower())
    elif token.isalpha() and history:
        history = history[:-1] + [history[-1] + token.lower()]
    else:
        history = history + re.findall(r"[\w'-]+", token.lower())
    return history[-5:]

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    history = [] if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = history[-1] if history else ''
    current = word_classes(word)
    earlier_be = any(x in BE_FORMS for x in history[-4:-1])
    emphasized = any(word_classes(x) & {'emphasis', 'intensity'}
                     for x in history[-3:])

    value = -0.0039
    for group in current:
        value += CONCEPTS[group][1]
        modifiers = WORD_MODIFIERS.get(group, {})
        if word.endswith('ed'):
            value += modifiers.get('ed', 0.0)
        if word.endswith('s'):
            value += modifiers.get('s', 0.0)
        if previous in BE_FORMS:
            value += modifiers.get('be', 0.0)
        if emphasized:
            value += modifiers.get('emphasis', 0.0)
    if current:
        if previous in BE_FORMS:
            value += -0.0997
        if emphasized:
            value += -0.2665
    if word in PREPOSITIONS:
        value += PREPOSITIONS[word]
        for group, rule in CONCEPTS.items():
            if group in word_classes(previous):
                value += rule[2]
                modifiers = LINK_MODIFIERS.get(group, {})
                value += modifiers.get(word, 0.0)
                if previous.endswith('ed'):
                    value += modifiers.get('ed', 0.0)
                if earlier_be:
                    value += modifiers.get('be', 0.0)
            else:
                for distance, old in enumerate(reversed(history[-5:])):
                    if group in word_classes(old):
                        value += rule[3] * 0.65 ** distance
                        break
    return (document, advance(history, token)), float(value)

programs.haiku:
"""Phrase detector for layers.1.mlp.down_proj:2758 (v3).

The component's activation is almost entirely set by a handful of two-word phrases: the
current token completes a fixed collocation, and the sign depends on the phrase. This
program predicts the component's activation from the previous token and the current token
only, using named word classes; everything else is predicted as 0.
"""
READS = ()

# evaluative adjective followed by a praise noun: "good job", "great work", "nice time"
PRAISE_ADJ = {"good", "great", "excellent", "nice", "best", "wonderful", "amazing", "fun", "super"}
PRAISE_NOUN = {"job", "work", "thing", "time", "deals", "luck", "life", "health", "grades", "interests"}
# modifier before a technical 'state' noun: "cold position", "standard form", "ill-posed"
STATE_ADJ = {"cold", "normal", "standard", "optimal", "better", "properly", "bad", "ill-", "ill",
             "usual", "canonical", "neutral", "working", "original", "comfortable", "-"}
STATE_NOUN = {"position", "positions", "positioned", "posed", "form", "forms", "formed"}
PUBLIC_BAD = {"relations", "records", "law", "sector", "accommodation", "access", "radio"}


def clean(s):
    return s.strip().lower()


