    raw = prefix.token_strings[-1]
    cur = clean(raw)
    prev_raw = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    prev = clean(prev_raw)
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if not same_doc:
        prev = ""
        prev_raw = ""
    value = 0.0
    if prev in PRAISE_ADJ and cur in PRAISE_NOUN:
        value = 1.5
    elif prev == "well" and cur in ("done", "-done", "-working", "working"):
        value = 2.5
    elif prev == "social" and cur == "media":
        value = -2.4
    elif prev == "self-host" and cur == "ed":
        value = -2.4
    elif prev == "public" and cur in ("health", "safety", "works"):
        value = 1.7
    elif prev == "public" and cur in PUBLIC_BAD:
        value = -1.5
    elif raw in ("富裕", "wealth", "rich") and prev in ("common", "共同", "", "Good", "good"):
        value = 2.0
    elif prev_raw == "公共" and raw in ("料", "事业"):
        value = -2.5
