programs.sol:
"""Approximate a source-file/location feature.

Negative pulses mark filenames, dependency directories, and the punctuation
and connective words in stack traces. Repeated middle dots (visible spaces
in formatting diagnostics) get a positive pulse. Other text stays near zero.
Only a short trailing context is retained; it resets with each document.
"""
import re

READS = ()
# Ordinary programming and data-file suffixes, grouped by language or format.
EXTENSIONS = {
    '.py': -3.87, '.pyc': -3.87,
    '.ts': -2.26, '.tsx': -2.26,
    '.js': -2.18, '.jsx': -2.18, '.mjs': -2.18,
    '.go': -0.63, '.java': -1.68, '.rs': -3.36,
    '.php': -3.14, '.rb': -3.09, '.pm': -1.68,
    '.c': -0.50, '.cpp': -0.50, '.h': -0.50,
    '.cc': -0.50, '.hpp': -0.50,
    '.json': -0.80, '.yaml': -0.80, '.yml': -0.80,
    '.toml': -0.80, '.ini': -0.80, '.cfg': -0.80,
    '.md': -0.10, '.txt': -0.10, '.rst': -0.10,
    '.sh': -0.50, '.bash': -0.50, '.dll': -2.74, '.so': -2.74,
}
DATA_FILES = {'.json', '.yaml', '.yml', '.toml', '.ini', '.cfg',
              '.md', '.txt', '.rst'}
SOURCE = r'\.(?:py|ts|tsx|js|jsx|go|java|rs|c|cc|cpp|h|php|rb|pm)'
LOCATION = re.compile(SOURCE + r':\d*(?::\d*)?$')


def predict(old, s):
    if len(s) > 1 and not s.strip('·'):
        return 2.61
    word = '' if not old or old[-1].isspace() else old.rsplit(None, 1)[-1]
    word = re.split(r'[\"\'`<>()=,;]', word)[-1]
    path = '/' in word or '\\' in word
    suffix = re.search(r'\.[a-zA-Z]+$', old)
    ext = suffix.group() if suffix else ''
    complete = '.' + s if old.endswith('.') else s
    if complete in EXTENSIONS:
        if complete == '.py' and re.search(r'\bFile [\"\'][^\n]+$', old):
            return -5.69
        return EXTENSIONS[complete]
    if s.isdigit():
        if ':' in word and LOCATION.search(old):
            return -6.16 if old.endswith(':') else -0.32
        return 0.0
    if s in ('-packages', '_packages') and path:
        if old.endswith(('site', 'dist')):
            return -16.5
    if s == '_modules' and old.endswith('node'):
        return -4.76
    # Python/Perl traceback connectives, including virtual source files.
    if s == ' line':
        if re.search(r'\.py[\"\'],\s*$', old):
            return -15.61
        if re.search(r'\.(?:py|pm)$|File [\"\']<[^>]+>[\"\'],\s*$', old):
            return -9.0
    if s == ' in':
        if re.search(r'\bline \d+,$|\.py:\d+,$', old):
            return -13.15
        if re.search(r'\.py(?::\d+:)?$', old):
            return -9.0
    if s == ' on' and ext == '.php':
        return -8.0
    if s == '):' and re.search(r'\.php\(\d+$', old):
        return -8.0
    # file:line:column and file(line,column) diagnostics.
    if s in (':', ':\n', ' :') and ext in EXTENSIONS:
        if s == ':\n':
            return -3.2
        return -7.0 if ext in DATA_FILES else -17.5
    if s in (':', ':\n') and re.search(r'\.[a-z]+:\d+$', old):
        return -7.51
    if s == '::':
        if ext in EXTENSIONS:
            return -8.34
        if re.search(r'\.py::\w+$', old):
            return -1.71
    if s in ('\",', "',") and ext == '.py':
        return -4.5
    if s in (' (', '(') and ext in EXTENSIONS and ext not in DATA_FILES:
        if s == '(' and ext == '.php':
            return -19.0
        return -6.09 if s == ' (' else -10.84
    if s in ('\n', '\n\n', '\\n') and path:
        return -1.51 if ext in EXTENSIONS else -0.15
    if s == '/':
        return -0.50 if path else -0.12
    if s == ':/':
        return -2.48
    if s == ':':
        if re.search(r'\d+\.\d+\.\d+\.\d+$', old) or old.endswith('(node'):
            return -2.4
        if re.search(r'node:internal/[^\s()]+$', old):
            return -5.5
    if s in ('/bin', '/lib', '/vendor', '/modules'):
        return -2.49
    return -0.04 if path and not s.isspace() else -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, (old + s)[-300:]), float(predict(old, s))

"""Recognize documentation references and their surrounding markup.

URLs, documentation paths, Markdown link destinations and 'for information,
see' instructions contribute positively. Selected non-Markdown file suffixes,
next/last, and test-pass markers contribute negatively.
There are also rules for chat spacing, middle-dot runs, and initial YAML
title/author labels. Context is a bounded text tail, reset at document changes.
Unrecognized text contributes approximately zero; this is not a general
semantic classifier of documentation.
"""
import re

READS = ()
FILE_SUFFIXES = {
    '.py', '.java', '.go', '.rs', '.php', '.cpp', '.sh',
    '.json', '.xml', '.txt', '.yaml', '.yml', '.html', '.mod',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, tail, dots_only = 0, '', True
    else:
        _, n, tail, dots_only = carry
    s = prefix.token_strings[-1]
    value = -0.001
    # The tokenizer separates the scheme from its punctuation.
    if s == '://':
        value = 1.04 if tail.endswith('https') else 0.33
    elif s == '/docs':
        value = 4.0 if 'google.com/' in tail else 2.0
    elif s == '/latest':
        value = 3.0 if 'docs.aws.amazon.com' in tail else 0.64
    elif s == '.md':
        if tail.rfind('](') > tail.rfind(')'):
            value = 5.4
        elif '/docs' in tail.split('\n')[-1]:
            value = 1.8
        else:
            value = 0.25
    elif s == '/api' and tail.rfind('](') > tail.rfind(')'):
        destination = tail[tail.rfind('](') + 2:]
        value = 4.3 if destination.startswith('/') else 0.35
    elif s in FILE_SUFFIXES:
        value = -0.30
    elif s == '/workspace':
        value = -0.30
    elif s == ' see':
        if re.search(r'information[^.!?]*,\s*$', tail):
            value = 2.4
        elif re.search(r'(?:details|comparison)[^.!?]*,\s*$', tail):
            value = 1.3
        elif re.search(r'\b[Ff]or[^.!?]*,\s*$', tail):
            value = 0.9
        else:
            value = -0.04
    elif s == ' PASS' and tail.rstrip().endswith('---'):
        value = -0.70
    elif s and set(s) == {'·'}:
        value = -0.867 if dots_only else 0.25
    elif s == '\n' and tail.endswith('<|im_start|>user'):
        value = 0.21
    elif s == '\n\n' and tail.endswith('</think>'):
        value = 0.20
    elif s == '-to' and tail.endswith('how') and '://' in tail:
        value = 2.5
    elif s == ' specified':
        value = 1.05 if tail.lower().endswith('the') else 0.29
    elif s == ' information':
        value = 0.48 if tail.lower().endswith('more') else -0.07
    elif s in {' last', ' next'}:
        value = -0.15
    elif s == '/java' and tail.endswith('/main'):
        value = -0.6
    elif s == 'a' and re.search(r'<a\s+(?:id|name)=[^<>]*></$', tail):
        value = 10.3
    elif s == '>' and re.search(r'<a\s+(?:id|name)=[^<>]*></a$', tail):
        value = 4.7
    elif s == 'IMPORTANT' and re.search(r'>\s*\[!$', tail):
        value = 5.9
    # Early front-matter title/author labels have strong responses.
    # Approximate their decay by halving per earlier colon-containing line.
    if n < 64 and re.match(r'^(?:<gh_stars>\d+\n)?---\n', tail):
        fields = sum(':' in line for line in tail.splitlines()[:-1])
        if s == 'title' and tail.endswith('---\n'):
            value = 3.3
        elif s == ':':
            if tail.endswith('\ntitle'):
                value = 28.2 * 0.5 ** fields
            elif tail.endswith('\nauthor'):
                value = 4.3 * 0.5 ** fields
    dots_only = dots_only and bool(s) and set(s) == {'·'}
    return (doc, n + 1, (tail + s)[-300:], dots_only), value

programs.haiku:
"""Layer-1 MLP down_proj component 2761, as a sparse reader of documentation links.

Mostly zero. What it reacts to, in plain terms:

- Markdown links to other documentation pages. Inside a link target "](...)", the
  ".md" file name and the path pieces ("/docs", "/sdk", "../") light it up, ".md" most
  strongly. Outside a link, ".md" is a weak positive.
- Web addresses: "https", "http", "www" and "://" are a weak positive.
- Source-code file extensions (".py", ".go", ".rs", ".java", ".json", ...) and
  workspace paths ("/workspace", "/testbed") in tool output are a negative, and so is
  the word "PASS" in test logs.
- The newline that opens a user turn ("<|im_start|>user" then "\\n"), and the blank line
  after "</think>", sit at a steady small positive.

The values are the average activations of each group measured on training rows. A
person can read the program as "documentation links up, source-file names and test logs
down". It leaves most positions at 0.
"""

READS = ()

WEB_WORDS = {"http", "https", "www", "://"}
DOC_LINK_PIECES = {".md", "/docs", "/sdk", "/api", "/latest", "/library", "/rest", "../", "#owner"}
CODE_EXTENSIONS = {
    ".py", ".go", ".rs", ".java", ".c", ".php", ".html", ".mod", ".json", ".yaml", ".yml",
    ".xml", ".jar", ".cfg", ".sh", ".spec", ".txt", ".r", ".net",
}
WORKSPACE_PATHS = ("/workspace", "/testbed")
TEST_PASS_WORDS = {" PASS", "PASS"}


def step(carry, prefix, upstream):
    """Activation at the newest token. `carry` is True while inside a "](...)" link target."""
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    before2 = prefix.token_strings[-3] if len(prefix.token_strings) > 2 else ""
    new_document = len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    in_link = bool(carry) and not new_document
    if "](" in token:
        in_link = True
    if ")" in token:
        in_link = False

    if token in DOC_LINK_PIECES and in_link:
        value = 5.5 if token == ".md" else 2.0
    elif token == ".md":
        value = 0.3
    elif token in DOC_LINK_PIECES:
        value = 0.5
    elif token.strip() in WEB_WORDS:
        value = 0.35
    elif token.strip() in CODE_EXTENSIONS:
        value = -0.3
    elif token.startswith(WORKSPACE_PATHS):
        value = -0.3
    elif token in TEST_PASS_WORDS:
        value = -0.4
    elif token == "\n" and before == "user" and before2 == "<|im_start|>":
        value = 0.2
    elif token == "\n\n" and before == "</think>":
        value = 0.2
    else:
        value = 0.0
    return in_link, value

"""Fires on 'such' and on words that take a prepositional or 'as' complement, when they
follow a noun or punctuation: participles of place, origin and relation ('X located in',
'X based on', 'X related to'), and some adjectives ('X responsible for', 'X similar to').
The strongest case is 'such' opening an example ('X, such as')."""
READS = ()
# participles of place, origin, attachment and relation: they take in/on/to/from/by/with next
PLACE_ORIGIN = {
    "located", "based", "related", "associated", "derived", "centered", "situated",
    "tailored", "aimed", "disposed", "confined", "powered", "adapted", "dedicated",
    "designed", "mounted", "aligned", "composed", "arranged", "hosted", "attached",
    "surrounded", "connected", "adorned", "caused", "defined", "directed", "inspired",
    "formed", "induced", "obtained", "founded", "filled", "issued", "stored", "linked",
    "coupled", "owned", "positioned", "belonging", "pertaining", "consisting", "depending",
    "relating", "characterized", "built", "devoted", "tied", "housed", "sourced",
}
# adjectives that govern a preposition (similar to, responsible for, subject to, due to)
ADJ_PREP = {
    "responsible", "capable", "due", "relative", "subject", "similar", "known", "equal",
    "available", "suitable", "consistent", "divisible", "adjacent", "parallel",
    "equivalent", "reminiscent", "pursuant", "greater", "dependent", "prior", "famous",
}
# function words: a noun phrase does not end in these (prepositions, determiners, auxiliaries...)
FUNCTION = {
    "of", "in", "for", "with", "to", "on", "by", "from", "at", "into", "about",
    "no", "any", "all", "the", "a", "an", "this", "that", "these", "those", "its",
    "their", "his", "her", "our", "your", "my", "is", "are", "was", "were", "be",
    "been", "being", "and", "or", "but", "as", "also", "well", "not", "so", "very",
    "more", "most", "have", "has", "had", "which", "who", "when", "where",
    "including", "like", "than", "some", "each", "every", "other", "such", "",
}

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if len(prefix.token_strings) < 2:
        return None, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    after_noun = prev not in FUNCTION and not prev.endswith("ly")
    if word == "such":
        return None, (0.6 if after_noun else -0.2)
    if word in PLACE_ORIGIN and after_noun:
        return None, (0.9 if word == "located" else 0.6)
    if word in PLACE_ORIGIN:
        return None, 0.3
    if word in ADJ_PREP and after_noun:
        return None, 0.2
    return None, 0.0

programs.sol:
"""A local Japanese spelling signal, with title-header and PHP-tag exceptions.

Recent kana gates a contrast between common Japanese kanji and Chinese-style
vocabulary. Token length, Japanese/Chinese word frequencies, and the shape of
a dictionary reading give a coarse lexical score. Time words and pronouns are
especially negative. Punctuation and incomplete UTF-8 characters use broad
classes rather than a table of token identities.
"""
from functools import lru_cache
from math import log10
import regex
import jmdict
from opencc import OpenCC
from wordfreq import get_frequency_dict

READS = ()
JAPANESE = get_frequency_dict('ja')
CHINESE = get_frequency_dict('zh')
SIMPLIFY = OpenCC('t2s')
KANA = regex.compile(r'\p{Hiragana}|\p{Katakana}')
HAN = regex.compile(r'\p{Han}+')
TIME_WORDS = set('今昔朝昼夜春夏秋冬') | set(
    '今年 去年 昨年 明日 昨日 今日'.split()
)
PRONOUNS = set('何誰彼私僕俺君')


def frequency(table, word):
    return max(2.0, 9 + log10(table.get(word, 1e-9))) - 4


@lru_cache(maxsize=None)
def spelling_score(raw):
    text = raw.decode('utf-8', 'replace')
    word = text.strip()
    value = 0.0
    if HAN.fullmatch(word):
        japanese = frequency(JAPANESE, word)
        chinese = frequency(CHINESE, SIMPLIFY.convert(word))
        if len(word) == 1:
            value = (-0.55 - 0.52 * japanese + 0.56 * chinese
                     - 0.36 * max(japanese, 0))
            readings = jmdict.readings(word)
            if readings:
                reading = readings[0]
                # A single Sino-Japanese syllable usually has this short shape;
                # other readings are a rough cue for native Japanese vocabulary.
                short_syllable = regex.fullmatch(
                    r'[ぁ-ゖ][ゃゅょ]?[いうきくちつん]?', reading
                )
                if len(reading) > 1 and not short_syllable:
                    value -= 0.98
        else:
            value = (1.5 + 0.46 * japanese + 0.20 * chinese
                     - 0.62 * (min(len(word), 4) - 2)
                     - 1.64 * max(japanese, 0))
        if word in TIME_WORDS:
            value -= 4.5
        if word in PRONOUNS:
            value -= 3.1
    elif regex.search(r'\p{Han}', word):
        value = -0.15

    if '\ufffd' in text:
        first = raw.lstrip()[:1]
        if first and 0xe4 <= first[0] <= 0xe9:
            value -= 1.0  # unfinished Han character
        elif raw and 0x80 <= raw[0] < 0xc0:
            value -= 0.93  # UTF-8 continuation
    if '。' in text:
        value -= 1.1
    if '「' in text or '『' in text:
        value -= 1.8
    if '」' in text or '』' in text:
        value -= 0.7
    if regex.fullmatch(r'[,，:：;；]+', word):
        value += 2.4
    elif regex.fullmatch(r'[.．?!]+', word):
        value += 1.3
    if any(c in text for c in '♪♫♬♩'):
        value -= 4.8
    if not word:
        value -= 0.42
    if word.isascii() and word.isdigit():
        value += 0.25
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        strength, previous, position = 0.0, '', 0
    else:
        _, strength, previous, position = carry
        strength *= 0.8
        position += 1
    if KANA.search(text):
        strength = 1.0
    value = strength * spelling_score(prefix.token_bytes[-1])
    if position == 1 and previous == 'Title' and text == ':':
        value = 14.98
    if previous.endswith('<?') and text == 'php':
        value = (3.43 if position == 1 else
                 2.15 if position == 2 else 0.6)
    return (doc, strength, text, position), float(value)

"""Approximate sparse responses to code comments and structured-text labels.

Operation descriptions are positive, especially articles after verbs near
comment starts. WordNet supplies the verb test. Creation and resource-
controller documentation get a few phrase rules. Metadata, example I/O
labels and test-result labels are negative. Initial chat/comment markers
and repeated middle dots have fixed values; everything else predicts zero.
The state resets at document boundaries and retains 400 recent characters.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

DOC_TAGS = set('''author version since see license module package param return
returns throws exception date generated brief file type'''.split())
CREATOR_FIELDS = {'Created', 'Updated', 'Generated', 'Copyright', 'By'}
AUXILIARIES = set('''be am is are was were been being have has had
do does did can will may must shall should would could'''.split())


@lru_cache(maxsize=4096)
def is_verb(word):
    return (word.lower() not in AUXILIARIES
            and 'verb' in wordnet.parts_of_speech(word.lower()))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous, quoted = '', '', False
    else:
        _, text, previous, quoted = carry
    token = prefix.token_strings[-1]
    word = token.strip()
