    view = text.replace(r'\n', '\n').replace(r'\t', '\t')
    line = view.rsplit('\n', 1)[-1]
    star = re.match(r'^\s*(?:\d+\s+)?\*\s*(.*)$', line)
    comment = star or re.search(
        r'(?:/{2,}|/\*+|#+|"""|\x27\x27\x27|<!--|\(\*)\s*(.*)$',
        line,
    )
    words = re.findall(r'[^\W\d_]+', comment.group(1)) if comment else []
    openings = list(re.finditer(r'/\*+|"""|\x27\x27\x27', view))
    fresh = False
    empty = False
    documentation = False
    if openings:
        opening = openings[-1]
        documentation = view[opening.start():].startswith(('/**', '/*!'))
        body = view[opening.end():]
        body_words = re.findall(r'[^\W\d_]+', body)
        fresh = '*/' not in body and len(body_words) < 3
        empty = '*/' not in body and not body_words
    if comment is None and quoted and fresh:
        comment = re.match(r'^\s*(?:\d+\s+)?(.*)$', line)
        words = re.findall(r'[^\W\d_]+', comment.group(1))
    banner = comment and (':::' in text or '+:+' in text or '#+#' in text)
    frontmatter = text.startswith('---\n') and '\n---' not in text[4:]
    value = 0.0

    if not text and token == '<|im_start|>':
        value = 0.698
    elif not text and word in {'*', '///'}:
        value = 1.5
    elif len(token) > 1 and set(token) == {'·'}:
        value = -0.615
    elif word == 'PASS' and line.rstrip().endswith('---'):
        value = -1.2
    elif word == 'of' and re.search(r'Test Suites:\s*\d+$', line):
        value = -0.9
    elif frontmatter and not line.strip() and word == 'title':
        value = -2.95
    elif frontmatter and text.count('\n') == 1 and word == ':' and previous.strip() in {
        'title', 'author', 'index'
    }:
        value = -2.0
    elif token == '>Title':
        value = -4.0
    elif word == 'Input' and line.rstrip().endswith('```'):
        value = -3.8
    elif word == 'Output' and not line.strip():
        value = -2.6 if re.search(r'Input:[^\n]*\n$', text) else -1.0
    elif word == 'Explanation' and not line.strip() and 'Output:' in text:
        value = -3.5
    elif word == ':' and line.rstrip().endswith('```Input'):
        value = -2.0
    elif word == ':' and line.strip() == 'Output':
        value = -0.6
    elif word == ':' and line.strip() == 'Explanation' and 'Output:' in text:
        value = -1.0
    elif word in DOC_TAGS and re.search(r'[@\\]\s*$', line) and empty:
        value = -1.6 if star else -0.6
    elif banner and word == ':' and previous.strip() == 'By':
        value = -3.5
    elif banner and word == 'by' and re.search(r'\d[\d:/ ]+$', line):
        value = -3.5
    elif comment and empty and not words and word in CREATOR_FIELDS:
        value = -5.0 if banner and word == 'By' else -1.6
    elif comment and word == 'by' and previous.strip() == 'Created':
        value = -3.0 if fresh and star else -0.5
    elif comment and not words and word in {'Dependencies', 'Location'}:
        value = -1.8
    elif comment and word == 'resource' and re.search(
        r'\b(?:the|a) specified$', line
    ):
        value = 3.2
    elif comment and word == 'specified' and re.search(
        r'\b(?:Update|Remove|Show) the$', line
    ):
        value = 1.0
    elif comment and word == 'form' and re.search(r'\bShow the$', line):
        value = 2.8
    elif comment and word == 'new' and len(words) < 4 and re.search(
        r'\b(?:Create[sd]?|Build|Construct[sd]?|Initialize[sd]?) (?:a|an)$', line
    ):
        value = 1.4
    elif comment:
        if (fresh and documentation and star and not words
            and word.istitle() and is_verb(word)):
            value = 0.1 if word.endswith('s') else 0.8
        elif (word in {'a', 'an', 'the'} and len(words) < 3
              and words
              and not comment.group(1).lstrip().startswith(('@', '\\'))):
            verb = words[-1]
            if verb.isalpha() and is_verb(verb):
                if fresh and star:
                    value = 0.8 if verb.endswith('s') else 1.8
                else:
                    value = 0.85 if quoted and fresh else 0.65
        elif word in {'if', 'whether'}:
            verb = previous.strip().lower()
            if verb.startswith('determin'):
                value = 0.8
            elif verb in {'check', 'checks', 'checking'}:
                value = 0.1
    # Keep only bounded recent text, and whether a docstring quote is open.
    fragment = text[-2:] + token
    if len(re.findall(r'"""|\x27\x27\x27', fragment)) % 2:
        quoted = not quoted
    return (doc, (text + token)[-400:], token, quoted), value

"""Detect academic credentials, degree completions, and fields of study.

Large responses mark PhD/doctoral/bachelor terminology, possessive degree
names, and 'in/of' introducing a degree's subject. Smaller responses mark
theses, titles, graduation and study backgrounds. Response sizes were
calibrated on training text, not token-ID lookups.
Only a bounded byte tail is kept, joining split words and Han characters.
"""
import re

READS = ()
ABBR = (r'(?:Ph\.?D|M\.?B\.?A|[MB]\.?(?:Sc|Tech|Eng|Ed|[AS])|[MB]\.E|'
        r'[MD]Phil|(?:LL|Ed|Th)\.?D|Ed\.?S|M\.?D|D\.?D\.?S|MBBS)\.?')
ABBREVIATION = re.compile(r'(?<![A-Za-z])' + ABBR + r'$')
CREDENTIAL = re.compile(
    r'(?<![A-Za-z])(?:(?i:degrees?|bachelors?|masters?|doctorate|diploma)|'
    + ABBR + r")(?:['’]s|['’])?\s*$")
EDUCATION = re.compile(
    r'\b(?:bachelors?|masters?|graduat\w*|undergraduate|college|university|'
    r'academic|medical|doctoral|PhD|earned|received|obtained|completed|'
    r'educational|studied|pursu\w*)\b', re.I)


def response(before, token, text):
    if not token and text[-1:] == before[-1:]:
        return 0.0
    word, lower = token.strip().lower(), text.lower()
    match = re.search(r'(\w+)\s*$', before)
    last = match[1].lower() if match else ''
    educated = bool(EDUCATION.search(before[-100:]))
    credential = bool(CREDENTIAL.search(before))

    # Chinese/Japanese and Korean academic qualifications.
    if text.endswith((
            '博士學位', '博士学位', '學士學位', '学士学位', '博碩士', '博碩')):
        return 12.2
    if text.endswith(('博士', '硕士', '碩士', '博士生')):
        return 6.8
    if text.endswith(('硕', '碩')):
        return 7.7
    if text.endswith(('学士', '學士', '学位', '學位', '修士')):
        return 2.0
    if text.endswith(('학위', '박사', '석사')):
        return 7.2

    if any(ch.isalpha() for ch in token):
        for pattern, value in (
            (r'\bph\.?d\.?$', 10.5),
            (r'\b(?:post[- ]?|pre[- ]?)?doctoral$', 7.1),
            (r'\bdoctorate$', 10.2),
            (r'\bbachelors$', 6.2),
            (r'\bbachelor$', 3.8),
            (r'\bbachel$', 3.1),
        ):
            if re.search(pattern, lower):
                return value
        match = ABBREVIATION.search(text)
        if match:
            if re.search(r'(?:MBA|[MB]\.?(?:Sc|Tech|Eng)|'
                r'[MD]Phil|(?:LL|Ed|Th)\.?D)\.?$', text):
                return 5.4
            context = text[max(0, match.start()-100):match.start()]
            if EDUCATION.search(context) or re.search(
                r'\b(?:a|an|his|her|my|their|with)\s*$', context.lower()):
                return 4.4
            return 0.4

    if word in ("'s", '’s', "'", '’') and last in {
            'bachelor', 'master', 'associate'}:
        return 5.0
    if word in {'degree', 'degrees'}:
        if credential:
            return 10.9
        if educated or last in {'my', 'his', 'her', 'your', 'their'}:
            return 5.1
        if last in {'a', 'an'}:
            return 2.1
        return 0.3 if word == 'degree' else 0.0
    if word in {',', '.,'} and ABBREVIATION.search(before.rstrip()):
        return 1.8

    if word == 'in':
        if credential:
            return 10.0 if ABBREVIATION.search(before.rstrip()) else 7.4
        if last in {'major', 'majoring', 'minor', 'concentration'}:
            return 3.9
        if last in {'background', 'residency', 'chair'}:
            return 3.7
        if educated and last in {
                'student', 'students', 'program', 'programs', 'studies', 'candidate'}:
            return 3.9
    if word == 'of':
        if last in {'bachelor', 'bachelors', 'doctor'}:
            return 9.1
        if last in {'master', 'masters'}:
            return 4.2
        if last in {'professor', 'professors'}:
            return 5.1
        if last in {'degree', 'degrees'}:
            return -0.2
    if word in {'in', 'from'} and last in {
            'graduate', 'graduated', 'graduating', 'graduation'}:
        return 3.6
    if word in {'professor', 'professors'}:
        return 0.8
    if re.search(r'\b(?:thesis|theses|dissertation)$', lower):
        return 6.2 if credential else 2.7
    if re.search(r'\bhonours$', lower):
        return 5.3
    if token.strip() == 'Ph' and last in {'a', 'an', 'my', 'his', 'her', 'their'}:
        return 3.1
    if credential and word in {'student', 'students', 'candidate', 'program', 'studies'}:
        return 3.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    new = (old + raw)[-400:]
    value = response(old.decode('utf-8', 'ignore'),
                     raw.decode('utf-8', 'ignore'),
                     new.decode('utf-8', 'ignore'))
    return (doc, new), value

"""Approximate local formatting cues in scraped conversations.

AM/PM timestamp endings are mostly negative; reply mentions are mostly positive
values, especially just after comment metadata. A single versus double newline
after a comment timestamp has opposite signs. Smaller rules cover attribution,
post identifiers and common embedded-link formats. Everything else is zero.
Only the last 250 characters are retained, resetting at document boundaries.
"""
import re

READS = ()
TIME = re.compile(r'(?<!\d)(\d{1,2}):\d{2}(?::\d{2})?[ \t]*$')
DATE = re.compile(
    r'\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\b'
    r'|\b\d{1,4}[-/]\d{1,2}[-/]\d{1,4}\b', re.I)
COMMENT_TIME = re.compile(r' at \d{1,2}:\d{2}$')


def predict(before, token):
    s = token.strip()
    low = s.lower()
    if low in ('am', 'pm'):
        time = TIME.search(before)
        if time:
            if token[0].isspace():
                value = -1.7 if s.isupper() else -1.1
                if s.isupper() and low == 'pm':
                    value -= 0.65
            else:
                value = -0.3 if s.isupper() else 0.1
            value -= 0.7 * bool(DATE.search(before[-100:]))
            value -= 0.3 * (len(time[1]) == 2)
            value += 0.5 * bool(re.search(r'\d:\d{2}:\d{2}$', before))
            return value
        return -0.25 if re.search(r'\d\s*$', before) else 0.0
    if low == '.m' and re.search(r'\d\s+[ap]$', before, re.I):
        return -0.6

    if '@' in token and re.fullmatch(r'\s*\(?@\w*', token):
        if s.startswith('(@'):
            return 1.8 if '—' in before[-90:] else 0.1
        if not before or token[0].isspace() or before[-1].isspace():
            line = before.rsplit('\n', 1)[-1]
            if before.rstrip().endswith('•'):
                return 5.1
            if not line.strip() and before:
                value = 0.9 - 0.3 * (len(line) > 1)
                value += 4.6 * bool(re.search(
                    r'\d:\d{2}(?:\s*[ap]m)?\s*$', before, re.I))
                value -= 0.8 * bool(re.search(
                    r'\b(?:def|class|import|public|private)\b|[{};]\s*$',
                    before[-150:]))
                return value
            if re.search(r'\b(?:hi|hello|thanks|hey)[,!\s]*$', line, re.I):
                return 3.0
            return -0.07

    if token in ('\n', '\n\n', ' \n', ' \n\n') and TIME.search(before):
        if COMMENT_TIME.search(before):
            return 1.25 if token.count('\n') == 1 else -1.7
        return 0.0
    if s == '•' and re.search(r'\d:\d{2}\s*$', before):
        return 1.7
    if s == ':' and not token.startswith(' '):
        if before.endswith('text preview'):
            return 2.4
        if re.search(r'\d{1,2}$', before) and DATE.search(before[-110:]):
            return -0.6 if re.search(r' at \d{1,2}$', before) else -0.07
    if low == 'by':
        if TIME.search(before):
            return 3.4
        if re.search(r'\basked\s*$', before, re.I):
            return 1.2
        if re.search(r'\bposted\s*$', before, re.I):
            return 0.8
    if low == 'posted' and before.endswith('Originally'):
        return 1.1
    if s == 'Originally' and before.rstrip().endswith('Quote:'):
        return 1.1
    if s == '.post' and re.search(r'blog-\d+$', before):
        return -6.0
    if s == '.com':
        if before.endswith('pic.twitter'):
            return 1.7
        if before.endswith('email@example'):
            return -0.6
        if before.endswith('i.imgur'):
            return 1.4
    if s == '.twitter' and before.endswith('pic'):
        return 0.8
    if s == '?v' and before.endswith('youtube.com/watch'):
        return 1.6
    if s == '»' and re.search(r'\d:\d{2}.*[ap]m\s*$', before, re.I):
        return -1.3
    if s == "'" and re.search(r'\b[A-Z][a-z]{2}\s+\d{1,2}$', before):
        return -0.4
    if s == '#':
        if TIME.search(before) or before.rstrip().endswith(('##', 'Answer')):
            return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(before, token)
    return (doc, (before + token)[-250:]), float(value)

programs.haiku:
"""Clock-time follow-ups in forum and comment timestamps.

Layer-1 MLP feature (one rank-one slice of the down projection). It is silent almost
everywhere. It reacts to the text right after a clock time such as "at 19:25" or
"06:22:44":
  - "AM"/"PM" (and "am"/"pm", "a.m.") that closes a clock time: strongly negative;
  - the "@" that opens a commenter's name after a timestamp ("Oct 8 '12 at 22:26\\n@name"):
    strongly positive, as is "by" in "06:22:44 by ...";
  - the bullet "•" that sits between such a timestamp and the name: mildly positive.
It also fires weakly on a few byline words ("asked by", "Posted by", "(@" in a tweet byline)
and is slightly negative on the colon of an hour in a date-time ("at 19:", "2011, 09:").
Everything else is predicted as 0.
"""

import re

READS = ()

# the text so far ends with a clock time, possibly followed by a few non-digit characters
AFTER_CLOCK = re.compile(r"\d:\d\d\D{0,4}$")
# the text so far ends with an hour in a date-time: "at 19", ", 09", "2 19"
HOUR_OF_DATETIME = re.compile(r"(?:at |, |\d )\d\d$")

MERIDIEM = {"PM": -3.0, "pm": -1.9, "AM": -2.0, "am": -1.4, ".m": -0.8}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    before = "" if (carry is None or new_doc) else carry  # the last 16 characters before cur
    word = cur.strip()
    value = 0.0
    if AFTER_CLOCK.search(before):
        if word in MERIDIEM:
            value = MERIDIEM[word]
        elif word == "@":
            value = 5.5
        elif word == "by":
            value = 2.5
        elif word == "•":
            value = 1.5
    elif word == "(@":
        value = 1.3
    elif word == ":" and HOUR_OF_DATETIME.search(before):
        value = -1.0
    elif word == "by" and before.rstrip().endswith(("asked", "posted", "Posted")):
        value = 1.5
    elif word == "Posted":
        value = 0.6
    return (before + cur)[-16:], value

programs.sol:
"""A local spelling-fragment approximation, not a semantic classifier.

An i-initial vowel/nasal fragment is usually positive after h and negative
following x or j. The vowel and nasal spelling determine the strength.
These effects are strongest when the preceding alphabetic piece is short.
The ue spelling has a particularly strong negative response after x.
A run of at least eight middle dots has a separate negative response.
Only the current token, preceding ASCII fragment, and dot-run length are
used; state resets at document boundaries. Other contexts return zero.
This captures a portion of the observed spelling effects, not the much
less systematic background variation.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, dots = ('', 0)
    if carry is not None and carry[0] == doc:
        previous, dots = carry[1:]
    dots = dots + len(token) if token and set(token) == {'·'} else 0
    state = (doc, token, dots)
    if dots >= 8:
        return state, -1.35

    tail = re.search(r'[A-Za-z]+$', previous)
    if tail is None:
        return state, 0.0
    fragment = tail.group()
    last = fragment[-1].lower()
    s = token.lower()
    short = len(fragment) <= 3
    scale = 1.0 if short else 0.2
    value = 0.0

    if re.fullmatch(r'ue[a-z]?', s):
        if last == 'x':
            value = -9.5 if s == 'ue' else -2.5
            if len(fragment) > 1 and not fragment.lower().endswith('ex'):
                scale *= 0.3
        elif last == 'h':
            value = 3.5 if s == 'ue' else 2.5
        elif last == 'j':
            value = -2.0 if s == 'ue' else -0.4
        elif last == 'y':
            value = -1.0
    elif re.fullmatch(r'i[aeoun][a-z]{0,3}', s):
        if last == 'h':
            bare = re.fullmatch(r'i[aeou]*(?:n|ng|nn|m|nh)?', s)
            if not bare:
                value = 0.3
            elif s == 'ing':
                value = 2.8
                if not short:
                    value = 0.05
                    scale = 1.0
            elif s.startswith('ie'):
                value = 2.0 if len(s) == 2 else 0.5
            elif s.startswith('io'):
                value = 2.4 if s.endswith('n') else 1.1
            elif s.startswith('ia'):
                value = 1.8 if s.endswith(('n', 'ng')) else 1.0
            elif s.startswith('iu'):
                value = 1.0
            else:
                value = 1.0 if s == 'in' else 0.25
        elif last == 'x':
            if s.startswith('in'):
                if s == 'ing':
                    value = -3.0 if len(fragment) == 1 else -1.0
                else:
                    value = -3.5
            elif s == 'ie':
                value = -4.0
            elif s == 'ia':
                value = -2.2
            else:
                value = -0.5
            if len(fragment) > 1 and not fragment.lower().endswith('ex'):
                scale *= 0.4
        elif last == 'j':
            if s.startswith(('ia', 'ie')):
                if s.endswith(('n', 'ng')):
                    value = -1.0
                else:
                    value = -3.0 if len(s) <= 3 else -0.5
            elif s.startswith('in'):
                value = -1.0
            else:
                value = -0.6
        elif last == 'y' and s == 'in':
            value = -1.3
        elif s == 'ing' and last == 'f' and len(fragment) == 1:
            value = 1.1
        elif s == 'ing' and last in 'eo' and short:
            value = 2.0 if fragment[0].isupper() else 0.5
    elif s == 'un' and last == 'i':
        value = 1.5
    elif s == 'i' and last == 'g':
        value = 0.45
    return state, float(value * scale)

"""Approximate a German-conditioned response to spelling pieces.

A fading tally of words' German frequency advantage supplies a language
confidence. In German-looking context, 'in' is strongly negative; a few
selected prepositions, adverbs and quantifiers are weaker negatives. Short
consonant clusters are positive, especially sch. Bare horizontal spaces
after prepositions also have a negative response. Smaller letter-piece and
hyphen rules supply corrections. The bounded tally adapts to language
changes and resets between documents. Many lexical effects remain omitted.
"""
from functools import lru_cache
import re
from wordfreq import zipf_frequency

READS = ()

# Common German prepositions: a bare space can continue their context.
PREPOSITIONS = set(
    'in bei nach im auf am an unter über für von vor zu um mit ohne '
    'gegen seit bis aus neben zwischen ab'.split()
)


@lru_cache(maxsize=100000)
def german_evidence(word):
    word = word.lower()
    if len(word) < 2 or not word.isalpha():
        return 0.0
    german = zipf_frequency(word, 'de')
    other = max(zipf_frequency(word, language)
                for language in ('en', 'nl', 'fr', 'es', 'it'))
    if max(german, other) < 3:
        return 0.0
    return max(-2.0, min(2.0, german - other))


def spelling_response(token, word_start, previous_word):
    if token and all(ch in ' \t' for ch in token):
        if previous_word == 'in':
            return -5.0
        if previous_word in PREPOSITIONS:
            return -2.6
        return -0.42
    text = token.strip()
    if text in {'-', '–', '—'}:
        return 0.56
    lower = text.lower()
    if word_start:
        if lower == 'in':
            return -5.5 if text[0].isupper() else -6.6
        if lower == 'all':
            return -4.0
        if lower == 'so':
            return -3.5
        if lower == 'fast':
            return -4.4
        if lower in {'von', 'auf', 'bei', 'im', 'mit', 'nach', 'am', 'für'}:
            return -1.05
    if lower in {'sch', 'schl', 'schr', 'schw', 'scha', 'sche',
                 'schi', 'scho', 'schu'}:
        return 3.5
    if lower.startswith('sp') and len(lower) <= 4:
        return 2.3
    if lower.startswith('str') and len(lower) <= 4:
        return 1.8
    if lower in {'st', 'sta', 'ste', 'sti', 'sto', 'stu', 'stä'}:
        return 1.1
    if lower == 'ch':
        return 1.7
    if re.fullmatch(r'(?:[bdfgkp][lr]|[fks]r|[fgks]l|[ks]k|kn|zw)', lower):
        return 1.2
    if len(lower) == 1 and lower in 'bcdfghjklmnpqrstwxz':
        return 0.5
    if lower == 'v':
        return -1.4
    if lower in {'re', 'le'}:
        return 1.7
    if lower in {'al', 'el'}:
        return -1.5
    if lower in {'ss', 'ess'}:
        return 1.7
    return 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, word, tally = carry
    word_start = not word or bool(token and token[0].isspace())
    previous_word = word.lower()
    tally *= 0.98
    for part in re.findall(r'[^\W\d_]+|[^\w]+|[\d_]+', token):
        if part.isalpha():
            word += part
        elif word:
            tally += german_evidence(word)
            word = ''
    tally = max(-8.0, min(8.0, tally))
    confidence = max(0.0, min(1.0, (tally + german_evidence(word)) / 2.0))
    value = confidence * spelling_response(token, word_start, previous_word)
    return (doc, word, tally), float(value)

programs.haiku:
"""A word that answers, reacts to or builds on something, followed by "to" or "on".

The component fires on the preposition after a verb or noun of responding, reacting or
acting upon something: "respond to", "reply to", "react to", "response to", "act on",
"comment on" (strongest, about 4 to 7). It fires more weakly after verbs of connecting or
relating ("adapt to", "subscribe to", "listen to", "relate to", "apply to"; about 1.5). It
is negative on the infinitive "to" after words such as "ready", "start", "forced",
"entitled" and "welcome" (about -1.5). Other cases: the colon of an email subject "Re:"
(about 3.5), the colon of a "Title:" that opens a document (about 16), and "import" at the
start of a line of Java or Kotlin code (about 1). Everything else is near zero."""

READS = ()

RESPOND = {"respond", "responds", "responded", "responding", "response", "responses",
           "reply", "replies", "replied", "replying", "reaction", "reactions", "react",
           "reacts", "reacted", "reacting", "comment", "comments", "commented", "act",
           "acts", "acted", "acting", "reflect", "reflects", "reflected", "reflecting"}
CONNECT = {"adapt", "adapting", "adapted", "subscribe", "subscribed", "subscribing",
           "listen", "listening", "listened", "listens", "connect", "connects", "connected",
           "connecting", "relate", "relates", "related", "relating", "apply", "applies",
           "applied", "applying", "speak", "spoke", "talk", "talked", "correspond",
           "corresponding", "corresponds", "click", "clicking", "agree", "agreeing"}
INFINITIVE = {"ready", "start", "started", "starts", "eager", "forced", "free", "entitled",
              "looking", "love", "liked", "option", "welcome", "susceptible", "vulnerable"}


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    cur = strs[-1].strip()
    if len(strs) < 2:
        return carry, 0.0
    prev = strs[-2].strip()
    if cur == "import" and strs[-2].endswith("\n"):
        return carry, 1.0
    if cur == ":":
        if prev == "Re":
            return carry, 3.5
        if prev == "Title" and len(strs) > 2 and strs[-3] == "<|endoftext|>":
            return carry, 16.0
    if cur in ("to", "on"):
        if prev.lower() in RESPOND:
            return carry, 5.0
        if prev.lower() in CONNECT:
            return carry, 1.5
        if prev.lower() in INFINITIVE:
            return carry, -1.5
    return carry, 0.0

"""Layer 1, MLP down-projection component 2774: a document-start detector with a
negative baseline that depends on the kind of token.

What it does, in plain terms:
- The first token of each document is read with no context, so it is set by the token
  alone. A word there gives a large positive value (capitalised words most, about +10;
  other words about +7); a digit or punctuation mark gives about +1 to +2; the chat marker
  <|im_start|> gives about +19.
- Every other token sits at a negative baseline of about -4.1. The first few tokens of a
  document sit lower (about -5.2) and the baseline climbs back to -4.1 over roughly 40 tokens.
- Articles and prepositions ("the", "The", "at", "in") are a little more negative.
- Formatting is less negative: line breaks around -3, tabs around -1.7, bare spaces -4.8,
  whitespace runs -3.5, escaped line breaks (backslash then n) about -1.
- Special tokens: <|im_end|> is strongly negative (-8); <|endoftext|>, the think and tool
  tags sit near 0.

Activations are predicted from the token string and the position within its document,
which is all the program reads. Fitted by hand to the component's activations on training rows.
"""

import math

READS = ()

SPECIAL_ZERO = {"<|endoftext|>", "</think>", "</tool_response>", "<tool_call>", "<|im_start|>"}
ARTICLES = {" the", " The", " at", " in"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    k = 0 if new_doc else carry + 1  # tokens since this document's first token
    if new_doc:
        word = s.strip()[:1]
        if s == "<|im_start|>":
            return k, 18.8
        if word.isupper():
            return k, 10.5
        if word.isalpha():
            return k, 7.0
        if word.isdigit():
            return k, 0.8
        return k, 2.0
    if s == "<|im_end|>":
        return k, -8.0
    if s in SPECIAL_ZERO:
        return k, 0.0
    if s == "\\n" or (s == "n" and prefix.token_strings[-2].endswith("\\")):
        return k, -1.0  # an escaped line break written as backslash-n
    if "\t" in s:
        return k, -1.7
    if "\n" in s:
        return k, -2.9
    if s == " ":
        return k, -4.8
    if s.strip() == "":
        return k, -3.5
    base = -4.1 - 1.1 * math.exp(-k / 40.0)
    if s in ARTICLES:
        return k, base - 1.0
    if s[:1] == " " and s[1:2].isalpha():
        return k, base - 0.4
    return k, base

programs.sol:
"""Approximate a document-reference and embedded-resource detector.

The strongest predictions are negative at Markdown destinations, Pandoc
anchors/citations, and HTML/TeX image inclusions. Smaller rules cover reference
attributes, URLs, supplementary material, and document-formatting markers.
Strengths are rounded training estimates; unrecognized tokens predict zero.
Only the last 256 characters are kept, resetting at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before = ""
    else:
        before = carry[1]
    token = prefix.token_strings[-1]
    stripped = token.strip()
    value = 0.0

    # A closing label followed by '(' starts a Markdown destination.
    if token.endswith(']('):
        label = before.rsplit('[', 1)[-1]
        opening = before.rfind('[')
        attached_to_word = (opening > 0 and
                            before[opening - 1].isascii() and
                            before[opening - 1].isalnum() and ' ' in label)
        # Avoid type parameters, array expressions and forum closing tags.
        if not (attached_to_word or label.startswith(('void ', '/')) or
                re.fullmatch(r'[A-Z]\s*,\s*[A-Z]', label)):
            value = -10.7
    elif token == '(' and before.endswith(']'):
        value = -10.7
    elif stripped == '#':
        if before.endswith(']('):
            value = -11.9
        elif token == '#' and before.endswith('{') and not before.endswith(r'\{'):
            value = -10.8
    elif stripped == '[@':
        if token.startswith(' '):
            value = -2.8
        elif before.endswith(('^', r'\[')):
            value = -6.0
        elif before.endswith('\xa0'):
            value = -2.5
        else:
            value = -4.4
    elif stripped == '@':
        if before.endswith('['):
            value = -8.5
        elif re.search(r'\[@[\w:;., @-]*$', before):
            value = -4.5

    # Attribute blocks attached to Markdown references and figures.
    elif stripped == '){' and '](' in before:
        value = -3.5
    elif stripped == ']{':
        value = -2.0
    elif stripped == '{}' and before.endswith(']'):
        value = -2.5
    elif token == '{':
        command = re.search(r'\\([A-Za-z]+)\*?$', before)
        if command:
            name = command[1].lower()
            if name.startswith('cite'):
                value = -2.4
            elif name in {'label', 'ref', 'eqref', 'autoref', 'begin', 'end'}:
                value = -1.2
        elif before.endswith('[]'):
            value = -6.0

    # HTML and TeX image inclusion, URLs, and documentation tags.
    elif stripped == 'graphics' and before.endswith(r'\include'):
        value = -10.7
    elif stripped == '<img':
        value = -4.9
    elif stripped == '="' and before.endswith(' src') and '<img' in before:
        value = -7.4
    elif stripped == 'src' and before.endswith('<img'):
        value = -2.8
    elif stripped in {'/', '../', '../../'} and before.endswith(']('):
        value = -4.5
    elif stripped == 'a' and before.endswith('<'):
        value = -2.8
    elif stripped == '<a':
        value = -2.0
    elif stripped == '://':
        value = -0.85 if before.lower().endswith('https') else -0.1
    elif stripped == 'summary' and before.endswith('</'):
        value = 2.6
    elif (stripped.lower() in {'material', 'information'} and
          before.lower().endswith('supplementary')):
        value = -5.8 if stripped.lower() == 'material' else -2.6
    elif stripped == 'plementary' and before.endswith('Sup'):
        value = -3.0
    elif stripped.lower() == 'supplementary':
        value = -3.8 if stripped[0].isupper() else -1.5
    elif token == ':' and (before == 'Title' or
                           before.endswith('<|endoftext|>Title')):
        value = 3.9
    elif token == ':' and before.endswith('---\ntitle'):
        value = -2.4
    elif stripped and set(stripped) == {'·'} and len(stripped) > 1:
        value = -1.14

    return (doc, (before + token)[-256:]), value

"""Recognize token-final -no fragments, especially -ano and -ino.

The response is larger when a short token completes that syllable than
when the whole word is one token. Cyrillic and Hangul are transliterated
for the same test. The Chinese name-transcription character 诺 and the
end-of-text marker have separate positive responses; repeated middle dots
have a negative one. Small offsets apply at document starts and after the
end-of-text marker.
"""
import re
import regex
from anyascii import anyascii

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    cyrillic = bool(regex.search(r'\p{Cyrillic}', token))
    transliterate = cyrillic or bool(regex.search(r'\p{Hangul}', token))
    text = (anyascii(token) if transliterate else token).lower()
    if text.isalpha():
        word = (previous + text)[-30:]
    else:
        match = re.search('[a-z]+$', text)
        word = match[0] if match else ''
    value = 0.0
    if token == '<|endoftext|>':
        value = 1.41
        word = ''
    elif token == '诺':
        value = 4.4
    elif len(token) > 1 and not token.strip('·'):
        value = -2.09
    elif word.endswith(('no', 'nos')) and 'o' in text:
        part = text.strip()
        if part in ('o', 'os') and previous.endswith('n'):
            value = (2.0 if part == 'os' else
                     7.0 if previous.endswith('in') else
                     4.5 if previous.endswith(('an', 'un')) else 3.0)
        elif part in ('no', 'nos'):
            value = (3.5 if previous and previous[-1] in 'aeiou' else 1.1)
            if not previous or not text.isalpha():
                value = 0.15
            if token.strip() == 'No':
                value = 0.0
        elif part in ('ano', 'ino', 'uno'):
            value = 3.8
            if part == 'ano':
                value = 7.0 if previous and previous[-1] in 'aeiou' else 3.4
        elif part in ('anos', 'inos', 'unos'):
            value = 4.1 if part == 'inos' else 2.1
        elif part in ('iano', 'ianos'):
            value = 2.1
        else:
            value = 1.2
        if cyrillic and len(part) > 3:
            value *= 0.15
        if text[:1].isspace():
            value *= 0.5
    if carry is None or carry[0] != doc:
        value -= 0.2
    elif carry[2]:
        value -= 0.15
    return (doc, word, token == '<|endoftext|>'), value

"""A sparse, local continuation detector.

Negative rules cover resource/utility compounds: water level/supply, material
content/source, companies, costs and conduits. Positive rules cover certain
kana continuations, especially the moraic nasal ん and geminated consonants.
A token-sized い or く immediately after Han text instead gets a negative value.
There are also Chinese measurement/storage compounds and Git ignore filenames.
These are approximate surface rules, not a complete account of the component.
Only a short byte tail and the previous token are carried between positions.
"""
from functools import lru_cache
import regex
import wordnet

READS = ()
ENERGY = set('power energy electricity electric electrical gas fuel oil heat solar'.split())
WATER = set('water sea ocean liquid'.split())
UTILITY = set('phone telephone mobile wireless internet cable service insurance credit card bank railroad railway rail'.split())
SOURCES = set('data information resource news light ground labor labour'.split())

@lru_cache(maxsize=8192)
def material(word):
    # Reject short function words that also name chemical elements in WordNet.
    return len(word) > 2 and bool(
        wordnet.categories(word) & {'noun.substance', 'noun.food'}
        or word in ('blood', 'paint')
    )


def predict(previous, token, tail):
    p, w = previous.strip().lower(), token.strip().lower()
    if token == 'ignore' and previous.lower().endswith('git'):
        return -1.8
    if w in ('supply', 'supplies'):
        if p in WATER:
            return -7.8 if w == 'supply' else -3.0
        if p in ('oil', 'fuel', 'gas', 'nutrient', 'fodder'):
            return -3.5 if w == 'supply' else -2.0
        return -1.6 if w == 'supply' else -0.2
    if w in ('cell', 'cells') and (
        p == 'solar' or tail.lower().endswith('photovoltaic')
    ):
        return 2.0
    if w in ('number', 'numbers') and p in ('phone', 'telephone'):
        return 1.4
    if w in ('level', '-level', 'levels'):
        if p in ('sea', 'ocean'):
            return -4.1
        if p in ('water', 'liquid'):
            return -7.2
        if material(p) or p in ENERGY:
            return -0.4
    if w in ('source', 'sources', 'content', 'contents', 'intake'):
        source = w.startswith('source')
        if p in WATER:
            return -3.9 if source else -2.6
        if material(p) or p in ENERGY or (source and p in SOURCES):
            return -1.6 if source else -1.4
    if w in ('company', 'companies', 'provider', 'providers', 'supplier', 'suppliers'):
        if p in ENERGY or p in WATER or p in UTILITY or material(p):
            return -2.2
    if w in ('price', 'prices', 'cost', 'costs', 'bill', 'bills', 'plan', 'plans'):
        if p in ENERGY or p in UTILITY or p in WATER or p in ('rent', 'heating', 'cooling'):
            return -2.6
    if w in ('line', 'lines', 'service', 'services', 'connection', 'connections'):
        if p in ENERGY or p in WATER or p in UTILITY or p in ('data', 'earth'):
            return -1.2
    if w in ('surface', 'surfaces'):
        if p in WATER:
            return -3.1
        if p in ('land', 'cell'):
            return -1.1
    if w in ('usage', 'consumption', 'meter', 'tank', 'gauge', 'cylinder'):
        if p in WATER or p in ENERGY or p in ('data', 'resource'):
            return -1.3
    if w == 'sugar' and p == 'blood':
        return -2.0

    # These are whole-token tests, not tests of every letter inside a token.
    han_end = bool(tail and regex.fullmatch(r'\p{Script=Han}', tail[-1]))
    if han_end and token in ('い', 'く'):
        return -3.0 if token == 'い' else -1.9
    if token == 'やり' and tail.endswith('水'):
        return -3.0  # Japanese watering compound, 水やり
    if token == 'ん' and regex.search(r'\p{Script=Hiragana}$', tail):
        return 3.6
    if previous and regex.fullmatch(r'\p{Script=Hiragana}+', previous):
        if token == 'い':
            if previous.endswith('て'):
                return 3.3  # auxiliary continuation, ...てい...
            return -1.9 if previous.endswith(('っぽ', 'にく')) else 1.5
        if token == 'く':
            return 1.5
        if token == 'う':
            return 1.8
        if token == 'っ':
            return 2.8
        if token in ('か', 'け', 'そ', 'す') and previous.endswith('っ'):
            return 3.7
        if token in ('き', 'ゅ', 'いて', 'じ'):
            return 1.1

    # Parallel Chinese resource quantities and containers.
    if p == '水' and token == '位':
        return -8.0
    if p in ('水', '金') and token in ('库', '庫'):
        return -2.8
    if p in ('水', '油', '糖') and token in ('分', '壓', '压', '器', '務', '路'):
        return -1.6
    if p in ('冷', '寒', '绿', '綠') and token == '意':
        return -6.1
    if token in ('意', '味') and previous and regex.fullmatch(r'\p{Script=Han}+', previous):
        return -0.7
    if p in ('网', '網', '火') and token == '速':
        return -3.0
    if p.endswith('数据') and token == '量':
        return -4.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, raw = ('', b'') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(previous, token, raw.decode('utf-8', 'ignore'))
    raw = (raw + prefix.token_bytes[-1])[-64:]
    return (doc, token, raw), value

