programs.sol:
"""Approximate a token's response when almost no context is available.

At document onset (including repetitions of its first token), C-like type
names and string escapes are strongly positive. Bare backslashes and
indented words are negative. Ordinary contextual tokens are near zero.
The opening decimal prefix '12' has a separate, sharp negative response.
Weak contextual responses distinguish dataflow words from type/shape words.
"""
from functools import lru_cache
import wordnet

READS = ()

COMMON_RETURN_TYPES = {'int', 'void', 'bool'}
OTHER_TYPES = {
    'float', 'double', 'char', 'long', 'unsigned', 'boolean',
    'string', 'str', 'uint',
}


TYPE_WORDS = COMMON_RETURN_TYPES | OTHER_TYPES | {
    'integer', 'byte', 'short', 'signed',
}
METADATA_WORDS = {
    'type', 'size', 'name', 'key', 'id', 'identifier', 'length',
    'width', 'height', 'shape', 'dimension', 'property', 'memory',
    'storage', 'address', 'number', 'value',
}
DATAFLOW_WORDS = {'data', 'input', 'output', 'result', 'response', 'return'}


@lru_cache(maxsize=16000)
def contextual_value(token):
    word = token.strip(' _\t\n').lower()
    if not word.isalpha():
        return -0.018 if token == ':' else 0.0
    forms = {word, *wordnet.base_forms(word)}
    if forms & METADATA_WORDS:
        return -0.045
    if forms & TYPE_WORDS:
        return -0.035
    if forms & DATAFLOW_WORDS:
        return 0.04
    return 0.0


def onset_value(token):
    word = token.strip()
    if token in COMMON_RETURN_TYPES:
        return 4.25
    if token in OTHER_TYPES:
        return 2.1
    if token in {r'\n', r'\r', r'\t', r'\b', r'\"'}:
        return 2.9
    if token in {'<|endoftext|>', '\x00'}:
        return 4.2
    if token == '\\':
        return -1.03
    if token.startswith('\t') and word:
        return -0.4
    if token.startswith('.') and token[1:2].isalpha():
        return 1.05
    if not word:
        return 0.33
    if word.isdecimal():
        return 0.42
    if word[:1].isupper():
        return 0.48
    return 0.24


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first, same, position, opening = token_id, True, 0, token
    else:
        _, first, same, position, opening = carry
        position += 1
        same = same and token_id == first
        if position == 1:
            opening += token
    value = onset_value(token) if same else contextual_value(token)
    if position == 1 and opening == '12':
        value = -3.3
    return (doc, first, same, position, opening), value

"""Approximate negative pulses at Latin capitalization joins.

A capitalized word piece glued to a token-ending capital run triggers
these rules. Vowel-initial pieces following a single capital get stronger
pulses, especially two-letter pieces. Pieces starting lowercase after
several capitals get a smaller pulse. Spaced words do not trigger them.
Separate rules handle initial `def`, initial `Title`, and its next colon.
These coarse case/length rules omit word-specific and background variation.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, age = '', 0
    else:
        _, previous, age = carry
    text = prefix.token_strings[-1]
    value = 0.0
    word = re.match(r'[A-Za-z]+', text)
    capitals = re.search(r'[A-Z]+$', previous)
    if word and capitals:
        word = word[0]
        n_caps = len(capitals[0])
        titlecase = len(word) > 1 and word[0].isupper() and word[1].islower()
        if titlecase:
            if n_caps > 1:
                value = -0.9
            elif word[0] in 'AEIOU':
                value = -2.5 if len(word) == 2 else -1.9
            else:
                value = -1.2
        elif word[0].islower() and n_caps > 1:
            value = -0.12 if len(word) == 1 else -0.3
    if age == 0 and text == 'def':
        value = -3.5
    if age == 0 and text == 'Title':
        value = -0.95
    if age == 1 and previous == 'Title' and text == ':':
        value = 5.25
    return (doc, text, age + 1), value

"""A pulse on a document's initial run of identical tokens.

Its height depends coarsely on script and word type: articles are weak,
Latin content words stronger, and kana negative. Traditional-form Han
gets a negative pulse too: a spelling proxy, not language identification.
After the initial run, predict zero.  These are approximations, not a
lookup table of the model's token responses.
"""
import regex
from opencc import OpenCC
from wordfreq import zipf_frequency

READS = ()
SIMPLIFY = OpenCC('t2s')
PRONOUNS = set('i you he she it we they me him her us them my your his '
               'our their its'.split())
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
IMPORT_WORDS = {'import', 'package', 'include', 'using'}


def pulse(text):
    word = text.strip()
    lower = word.lower()
    if text == '<|endoftext|>':
        return 24.9
    if text.startswith('<|'):
        return 5.1
    if not word:
        if text == ' ':
            return 6.9
        if set(text) == {' '}:
            return 11.6
        if '\n' in text:
            return 9.3
        return 12.4 if set(text) == {'\t'} else 10.5
    if regex.search(r'\p{Hiragana}|\p{Katakana}', word):
        return -10.9
    if regex.search(r'\p{Han}', word):
        return -7.9 if SIMPLIFY.convert(word) != word else 5.4
    if regex.search(r'\p{Hangul}', word):
        return 3.6
    if regex.search(r'\p{Cyrillic}|\p{Arabic}', word):
        return 7.4
    if word.isascii() and word.isdigit():
        return 6.1 if int(word) < 3 else 9.5
    if lower in IMPORT_WORDS or lower.startswith('#include'):
        return 4.1
    if word.isascii() and word.isalpha():
        upper = word[0].isupper()
        if lower == 'a':
            return -1.0
        if lower == 'an':
            return 8.2 if upper else 4.5
        if lower == 'the':
            return 3.0 if upper else 1.0
        if lower in DEMONSTRATIVES:
            return 2.9 if upper else 6.5
        if lower in PRONOUNS and (len(word) > 1 or word == 'I'):
            return 5.4
        if len(word) == 1:
            return 7.3 if upper else 8.9
        frequency = max(0.0, zipf_frequency(lower, 'en') - 4.0)
        return (10.6 + 1.5 * upper - 1.4 * text.startswith(' ')
                - 0.64 * frequency)
    if word == '\ufffd':
        return 4.6
    return 8.8 if word.isascii() else 6.9


def step(carry, prefix, upstream):
    token = prefix.token_ids[-1]
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if start:
        value = pulse(prefix.token_strings[-1])
        return (token, value, True), value
    first, value, initial_run = carry
    initial_run = initial_run and token == first
    return (first, value, initial_run), value if initial_run else 0.0

programs.haiku:
"""Layer-1 MLP component 2789 (down_proj): a "document-start" detector.

What it does: it is silent everywhere except on the first token of a document.
A document starts at the first token of each row and wherever the document id
changes inside a packed row (right after a <|endoftext|> boundary). There the
component writes a large activation (about 8 on average, up to 25). Elsewhere
it is near zero. (Its role in the model is not verified here; the switch-off
test shows only a small effect on next-token predictions.)

How big it is depends on which token starts the document, in rough classes:
  - articles, pronouns and determiners ("The", " the", "A", "I", "This", ...)
    give a weak signal (about 1);
  - CJK characters give a medium signal (about 4.5);
  - capitalised words (names, titles) give a strong one (about 11);
  - everything else gives about 8.5.
The exact value is a fixed function of the first token's identity, so these
classes are a readable approximation of a per-token lookup table.
"""

READS = ()

DETERMINERS = {
    "a", "an", "the", "this", "that", "these", "those", "i", "it", "you", "he",
    "she", "we", "they", "there", "my", "your", "his", "her", "our", "their", "its",
}


def _is_cjk(text):
    return any("぀" <= c <= "鿿" or "가" <= c <= "힯" for c in text)


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    word = prefix.token_strings[-1]
    if word.strip().lower() in DETERMINERS:
        value = 1.0
    elif _is_cjk(word):
        value = 4.5
    elif word[:1].isupper():
        value = 11.0
    else:
        value = 8.5
    return carry, value

programs.sol:
"""Sparse text-pattern approximation, not a lexical activation table.

Chinese 一 ('one') constructions use dictionary verb, motion, time and
restrictive-description senses to set their strength. Also mark document-initial
code declarations, URL separators, null literals and hexadecimal escapes.
Vietnamese accented word continuations and runs of middle dots are negative.
Document-initial tokens otherwise get a small script-dependent baseline.
"""
import unicodedata
import cedict
from functools import lru_cache
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
LATIN = regex.compile(r'\p{Script=Latin}')
DECLARATIONS = set('''
    import from package using const let var class interface public private
    protected def function export namespace struct enum typedef include
'''.split())
HEADERS = {'#!/', '<?', '<?php', '#include', '#pragma'}
NULLS = {'null', 'nil', 'None', 'NULL', 'nullptr'}
MOTION = ('move', 'turn', 'pull', 'push', 'look', 'glance', 'stare',
          'stop', 'start', 'jump', 'shake', 'rise', 'fall', 'walk', 'step')
TIME = ('year', 'day', 'time', 'life', 'night', 'evening', 'morning',
        'moment', 'season')
DESCRIPTION = ('only', 'mere', 'just', 'toward', 'true', 'genuine',
               'sincere', 'wholehearted')


@lru_cache(maxsize=4096)
def one_phrase(text, after_one):
    senses = cedict.glosses(text)
    gloss = '; '.join(senses).lower()
    if not after_one:
        return 0.35 if any(w in gloss for w in TIME) else 0.05
    value = 0.2
    if any(s.lower().startswith('to ') for s in senses):
        value += 0.45
    if any(w in gloss for w in MOTION):
        value += 0.35
    if any(w in gloss for w in DESCRIPTION):
        value -= 0.7
    return value


INITIAL_SCRIPTS = (
    ('Hangul', -0.5), ('Cyrillic', -0.14), ('Han', -0.07),
    ('Hiragana', -0.08), ('Katakana', -0.08),
)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip()
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if first else prefix.token_strings[-2]

    if word and set(word) == {'·'} and len(word) > 1:
        return None, -1.0 if first or previous == text else -0.2
    if text == '://':
        return None, 0.15
    if word in HEADERS:
        return None, 0.52 if first else 0.13
    if first and word in DECLARATIONS:
        return None, 0.6
    if word in NULLS:
        return None, 0.08
    if word.startswith('\\x'):
        return None, 0.07

    if first:
        value = -0.04
        for script, baseline in INITIAL_SCRIPTS:
            if regex.search(r'\p{Script=' + script + '}', text):
                value = baseline
                break
        else:
            if word.isdigit():
                value = -0.06
            elif word and all(unicodedata.category(c).startswith('P')
                              for c in word):
                value = 0.035
        return None, value

    if HAN.search(text):
        if previous.endswith('一'):
            return None, one_phrase(text, True)
        if text.startswith('一') and len(text) > 1:
            return None, one_phrase(text, False)

    if text and not text[0].isspace() and LATIN.search(text):
        if previous.rstrip().endswith(('đ', 'Đ')):
            return None, -0.6
        if LATIN.search(previous):
            marks = unicodedata.normalize('NFD', text)
            if ('\u0309' in marks or '\u0323' in marks or
                    regex.search(r'\p{M}{2}', marks)):
                return None, -0.14
    return None, 0.0

"""A local escape-punctuation detector with a few lexical side responses.

Backslash-escaped quotes are mainly negative, much more strongly when quote
and backslash are in separate tokens. Adjoining punctuation and doubled
backslashes modify that response. Some other escaped symbols respond too.

Read-more labels and selected built-in constructors after `new` are positive;
List/Set/Map constructors are negative. Only the latest two tokens in the
current document are used. Uncovered lexical responses are left at zero.
"""
READS = ()


def escaped_punctuation(token, previous):
    if previous.endswith('\\'):
        if token.startswith('"'):
            if token.endswith((';', '][', ')]')):
                return -3.5
            if token.endswith(':'):
                return -0.7
            if token.startswith('"/'):
                return -8.5
            if token.endswith('.'):
                return -5.3
            return -6.5
        if token.startswith('\\"'):
            return -0.9 if previous.endswith('\\\\') else 0.6
        if token.startswith('$'):
            return -2.7
        if token == '[':
            return -0.65
        if token == '_':
            return -0.9
        if token == '0':
            return -1.2

    if '\\"' in token:
        before, after = token.split('\\"', 1)
        value = -1.8 * 0.72 ** len(after)
        if before.strip() not in ('', '('):
            value *= 0.75
        return value
    if "\\'" in token:
        return -0.95
    if '\\$' in token:
        return -0.35
    if '\\<' in token or '\\%' in token or '\\-' in token:
        return -0.28
    return 0.0


def familiar_phrases(token, previous):
    # A web page's read-more link.
    if previous.strip() == 'Continue':
        if token == ' Reading':
            return 9.3
        if token == ' reading':
            return 3.0

    # A new-object expression; different kinds of built-ins have different signs.
    if previous.lstrip(' (<={').strip() == 'new':
        name = token.strip()
        if name == 'Date':
            return 6.1
        if name == 'Error':
            return 3.4
        if name in {'File', 'Promise'}:
            return 2.4
        if name in {'int', 'byte', 'char', 'double', 'boolean', 'float', 'string'}:
            return 3.2
        if name in {'List', 'Set', 'Map'}:
            return -3.8
    return 0.0


def step(carry, prefix, upstream):
    same_document = (prefix.position > 0 and
                     prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2] if same_document else ''
    token = prefix.token_strings[-1]
    value = escaped_punctuation(token, previous)
    if value == 0.0:
        value = familiar_phrases(token, previous)
    return None, value

"""A sparse mixture of spelling cues, rather than one semantic category.

Negative cues: river/name character 川, Sichuan spellings 四川 and 蜀,
and the need/require spellings 需, 须, and 不必 ("need not"). Simplification
also merges beard-form 鬚 into 须. Negation weakens 需/须. Chinese character
completions across byte tokens get twice the whole-token response.
LaTeX \\quad is negative; \\include and middle-dot runs are positive.
There is also a positive response to the second digit of document-initial
12. Other tokens are zero: most weak and contextual variation is omitted.
"""
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, tail, position = '', b'', 0
    else:
        _, previous, tail, position = carry

    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    fragmented = bool(raw) and 0x80 <= raw[0] < 0xC0
    # Recover a character whose leading UTF-8 bytes were in earlier tokens.
    if fragmented:
        token = (tail + raw).decode('utf-8', errors='ignore')[-1:]
    word = SIMPLIFY.convert(token) if token and not token.isascii() else token

    value = 0.0
    if word == '川':
        value = -4.8
    elif word == '蜀':
        value = -2.5
    elif word.startswith('四川'):
        value = -3.3 if word == '四川' else -1.4
    elif word in {'须', '需'}:
        value = -3.5 if word == '须' else -1.5
        if previous in {'无', '無', '不'}:
            value *= 0.55
    elif word == '不必':
        value = -0.7
    if fragmented:
        value *= 2.0

    if token == 'quad' and previous.endswith('\\'):
        value = -2.4
    elif token == 'include' and previous.endswith('\\'):
        value = 1.3
    elif len(token) > 1 and set(token) == {'·'}:
        value = 0.58
    elif position == 1 and previous == '1' and token == '2':
        value = 2.06
    carry = (document, prefix.token_strings[-1], (tail + raw)[-3:], position + 1)
    return carry, value

programs.haiku:
"""Negative detector for the Chinese character 川 (chuān, "river"), the
Sichuan/Hunan place-name characters (蜀, 湘, 渝, 四川, 湖南), and the
"must / need" characters (须, 須, 需), plus the LaTeX \\quad command.

On each token, the program predicts a negative activation of the
component, with the size set by how strongly the character responds.
Everything else is predicted as 0 (the component is silent).
"""

READS = ()

# Token -> typical activation (negative: the component is pushed down).
RIVER_PLACE = {"川": -4.8, "四川": -3.1, "四川省": -1.0, "蜀": -2.7, "渝": -0.3, "湘": -0.8, "湖南": -1.4}
MUST_NEED = {"须": -3.9, "須": -3.5, "需": -1.6}
LATEX_QUAD = -1.2


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in RIVER_PLACE:
        return None, float(RIVER_PLACE[tok])
    if tok in MUST_NEED:
        return None, float(MUST_NEED[tok])
    if tok == "quad" and len(prefix.token_strings) > 1 and prefix.token_strings[-2].endswith("\\"):
        return None, LATEX_QUAD
    return None, 0.0

programs.sol:
"""A lexical defense/fend detector, with a few orthographic side responses.

Defense words give the largest negative predictions.  Split stems are handled
by retaining the last word, and inflections and capitals have different gains.
Some East Asian spellings and unfinished UTF-8 prefixes are also negative.
Underscore-led names after ``def`` and a receiver parenthesis after Go's
``func`` are positive. Smaller rules cover punctuation and other f-stems.
This is a spelling/context approximation, not general reasoning about defense.
"""
import re
import codecs
import unicodedata
from functools import lru_cache
import regex
from pypinyin import lazy_pinyin

READS = ()


@lru_cache(maxsize=8192)
def roman(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c)).lower()


@lru_cache(maxsize=8192)
def fang_character(text):
    return (len(text) == 1 and text != '方'
            and regex.fullmatch(r'\p{Script=Han}', text)
            and lazy_pinyin(text)[0] == 'fang')


def response(s, before, previous):
    t = s.strip()
    if t in ('防', '防御', '防禦'):
        return -6.0
    if '防' in t:
        return -0.9
    if t == '守':
        return -1.7
    if t == '방':
        return -5.5
    if t == 'phòng':
        return -4.5
    if fang_character(t):
        return -1.5
    if t.startswith('защит'):
        return -2.0
    if t and set(t) == {'·'}:
        return -1.15 if len(t) > 1 else 0.0
    if previous.strip() == 'def' and s[:1].isspace():
        if t.startswith('__'):
            return 2.4
        if t.startswith('_'):
            return 3.3
        if t == 'self':
            return 5.0
        if t.startswith('['):
            return 3.5
        if t == 'test':
            return 0.7
        return 0.0
    if previous.strip() == 'func' and t == '(':
        # Use a smaller gain for numbered source listings.
        numbered = re.search(r'\d[ \t]*func$', before)
        return 0.3 if numbered else 2.6
    if t == 'php' and before.endswith('<?'):
        return -1.9
    if t == 'otherwise':
        return 1.6 if previous.strip() == 'or' else 0.45
    if t == '@':
        return 1.6 if previous.strip().upper() == 'SET' else -0.23
    if s == ' /':
        return -0.24

    match = re.search(r'[^\W\d_]+$', before) if s[:1].isalpha() else None
    left = match.group() if match else ''
    old, word = roman(left), roman(left + s).strip()
    current = roman(s)
    if 'f' not in word:
        return 0.0

    def new(pattern):
        return re.search(pattern, word) and not re.search(pattern, old)

    if new('defensiv'):
        return -3.5 if word.endswith('ly') else -6.3
    if new(r'defen[cs]|defesa'):
        if not re.search(r'defen[cs]|defesa', current):
            return -9.8
        if s.startswith(' ') and t[:1].isupper():
            return -4.4 if previous.strip() == 'of' else -11.5
        if not s[:1].isspace() and not t[:1].isupper():
            return -5.5
        return -5.8 if word.endswith(('enses', 'ences')) else -7.3
    if new('defend'):
        if 'defendant' in word:
            return -0.3
        if 'defend' not in current:
            return -7.5
        if 'defender' in word:
            return -3.3
        return -3.0 if word.endswith(('ed', 'ing')) else -5.1
    if new('defen'):
        return -3.2
    if new(r'offen[cs]|offesa'):
        return -1.3 if re.search(r'offen[cs]|offesa', current) else -4.5
    if new(r'^fend'):
        return -4.0 if left else -2.5
    if left and new('feder') and roman(t) == 'eder':
        return -2.1
    if left and new(r'confess|professed'):
        return -2.8
    if left and new('forens'):
        return -4.5
    if left and new(r'^f(?:ang|eng)'):
        return -3.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, previous, pending = '', '', b''
    else:
        _, before, previous, pending = carry
    was_split = bool(pending)
    raw = pending + prefix.token_bytes[-1]
    s, consumed = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[consumed:]
    value = response(s, before, previous)
    if pending == '防'.encode('utf-8')[:2]:
        # This unfinished character prefix is shared by 防, 阻, 阿, etc.
        value = -8.0
    elif was_split and fang_character(s.strip()):
        value = -4.0
    return (doc, (before + s)[-80:], s, pending), value

programs.haiku:
"""Layer-1 MLP down_proj component 2797, a hand-written approximation.

What it does: the component is mostly silent. Its clearest behaviour is on
(1) the Cyrillic soft sign "ь" and hard sign "ъ" when they sit inside a word
(strongly negative, about -2.4), with syllables like ья/ью/нь/ю/ё weaker negatives;
(2) Chinese words for "special / major / serious" (特殊, 重大, 严重, 恶劣, 典型, 专项, 事项, 严肃)
which push it positive, weaker for 重要 and similar adjectives;
(3) the Chinese locative 里/裡 ("in / inside", as in 平日里), negative.
Everything else is near zero. Each rule reads only the current token.
"""
READS = ()
SOFT_SIGNS = {"ь", "ъ", "Ь", "Ъ"}
SOFT_ENDINGS = {"ья", "ью", "нь", "ю", "ё"}
IMPORTANT = {"特殊", "特殊的", "重大", "严重", "严重的", "恶劣", "典型", "专项", "事项", "严肃", "的重大"}
IMPORTANT_WEAK = {"重要", "有关", "消费", "专门", "独特", "特别", "必要", "特定"}
INSIDE = {"里", "裡", "里的", "裡的"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in SOFT_SIGNS:
        v = -2.4
    elif tok in SOFT_ENDINGS:
        v = -0.5
    elif tok in IMPORTANT:
        v = 2.0
    elif tok in IMPORTANT_WEAK:
        v = 0.5
    elif tok in INSIDE:
        v = -1.0
    else:
        v = 0.0
    return None, v

programs.sol:
"""A document-entry pulse and a smaller comma/phrase-boundary response.

The entry pulse is smaller on whitespace, digits and punctuation than on
words. Bare capitalized words have a larger pulse than space-led words.
Comma responses are reduced in rapid lists, after discourse signposts,
and near code-like punctuation. Other positions are approximated by zero.
"""
READS = ()

SIGNPOSTS = frozenset('however therefore thus hence meanwhile furthermore '
                     'moreover alternatively wait hmm well yes no first '
                     'second finally indeed nevertheless nonetheless'.split())

PRONOUNS = frozenset("i you he she it we they me him her us them".split())
PREPOSITIONS = frozenset(
    "of for in on at by to from with about into over under".split()
)
ARTICLES = frozenset("a an the".split())

def entry_value(text):
    s = text.strip()
    if text.startswith('<|'):
        return 13.6
    if not s:
        if '\t' in text:
            return 11.0
        if '\n' in text:
            return 4.3
        return 4.4 + min(5.0, 0.7 * (len(text) - 1))
    if s.isdigit():
        return 5.7
    if not any(c.isalnum() for c in s):
        if all(c in '.。!?！？' for c in s):
            return 5.1
        if all(c in '-–—' for c in s):
            return 6.5
        if all(c in ')]}' for c in s):
            return 6.4
        if all(c in '([{' for c in s):
            return 5.8 if text.startswith(' ') else 9.5
        if any(c in '\"\'' for c in s):
            return 10.0
        return 8.5
    if any(ord(c) > 127 for c in s):
        return 12.1
    word = s.lower()
    if text.startswith(' '):
        if word in PREPOSITIONS:
            return 9.7
        if word in ARTICLES:
            return 9.9 if word == 'the' else 15.3
        if word in PRONOUNS:
            return 12.0
        return 11.0
    if word in PRONOUNS:
        return 19.0
    if word in ARTICLES:
        return 13.1 if word == 'the' else 17.5
    if word in PREPOSITIONS:
        return 14.5
    if len(s) == 1 and s.isupper():
        return 14.7
    return 16.2 if s[0].isupper() else 13.8


SIGNPOST_PHRASES = ('for example', 'for instance', 'of course', 'in fact',
                    'in addition', 'in particular', 'in short', 'in conclusion',
                    'on the other hand')


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        return (doc, text, text[-160:], 100), entry_value(text)

    _, previous, recent, comma_age = carry
    prev = previous.strip().lower()
    is_comma = ',' in text or text in {'，', '、'}
    value = 0.0
    if is_comma:
        value = 1.05
        if text in {'，', '、'}:
            value -= 0.45
        elif text != ',':
            value -= 0.65
            if text.rstrip().endswith('),'):
                value += 0.25
        if prev.isdigit():
            value -= 0.35
        signpost = (prev in SIGNPOSTS or
                    recent.lower().rstrip().endswith(SIGNPOST_PHRASES))
        if signpost:
            value -= 0.65
        if comma_age < 3:
            value -= 0.5
        if '`' in recent or ';' in recent or ' = ' in recent:
            value -= 0.25
        comma_age = 0
    return (doc, text, (recent + text)[-160:], comma_age + 1), value

"""A Mandarin manner/adverb signal, plus commas that close substantial clauses.

CC-CEDICT supplies Chinese meanings; JMdict recognizes Japanese efficiency
compounds. Size/duration constructions are also recognized. Split UTF-8 and
Han words are joined across tokens. Clause commas depend on clause length
and introductory material; Chinese list separators are kept near zero.
"""
import re
import codecs
from functools import lru_cache
import cedict
import jmdict
import opencc
import regex

READS = ()
_SIMPLIFY = opencc.OpenCC('t2s')
_HAN = regex.compile(r'\p{Script=Han}+$')
_KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
# Familiar semantic families of adverbial modifiers; numbers are typical strengths.
MANNER = (
    ('speed', r'^(fast|high-speed|rapid|speedy)\b|as quickly as possible', -1.7),
    ('ease', r'\b(effortless|uncomplicated|without a hitch|smoothly|'
     r'offhandedly)\b', -1.6),
    ('continuity', r'\b(continuous|consecutive|to last|uninterrupted)\b', -1.0),
    ('efficiency', r'\b(efficient|efficiency|effective)\b', -1.0),
    ('automation', r'\bautomatic\b', -1.2),
    ('completeness', r'^(comprehensive|all-around|all around|omnidirectional)\b', -1.0),
    ('quality', r'\b(high quality|precision|accurate|precise)\b', -1.0),
    ('success', r'\b(successful|fruitful)\b', -0.7),
    ('normality', r'^normal;', -0.8),
    ('promptness', r'\b(timely|promptly|immediately|real time)\b', -0.8),
    ('freedom', r'free \(of charge\)|free; unrestricted', -0.8),
    ('independence', r'^independent|^alone;', -0.5),
    ('care', r'\b(conscientious|earnest|attentively|meticulous|'
     r'kindness|gentleness|cordial)\b', -0.4),
    ('method', r'^how$|^way; method; manner|^method; way; means|'
     r'^nominal$|^posture|^angle of view', -0.3),
    ('extent', r'^depth$|^scale$|^scale; scope|substantially;|close range', -0.8),
    ('legality', r'according to law|within the rules|violate the rules', -0.6),
    ('intensity', r'\b(frantic|unbridled|insane|craziness)\b', -0.5),
    ('availability', r'at any time|anytime|entire journey|whole process', -0.5),
)
PATTERNS = tuple(re.compile(p, re.M) for _, p, _ in MANNER)
PRIMARY_SENSE = {'speed', 'continuity', 'completeness', 'promptness', 'care'}
INTRO = re.compile(r'\b(however|therefore|moreover|furthermore|consequently|meanwhile)\b|'
                   r'in (fact|addition|short)|at (present|that time|the same time)|currently')

@lru_cache(maxsize=32768)
def meaning(word):
    glosses = cedict.glosses(word)
    if not glosses:
        japanese = jmdict.glosses(word)
        if not any(re.search(r'\befficiency\b', g) for g in japanese):
            return -1 if japanese else -2
        glosses = japanese
    gloss = '\n'.join(glosses).lower()
    for i, pat in enumerate(PATTERNS):
        primary = MANNER[i][0] in PRIMARY_SENSE
        senses = glosses[0].lower() if primary and glosses else gloss
        if pat.search(senses):
            return i
    return -1 if glosses else -2

@lru_cache(maxsize=8192)
def introductory(word):
    return bool(INTRO.search('\n'.join(cedict.glosses(word)).lower()))


@lru_cache(maxsize=32768)
def simplify(text):
    return _SIMPLIFY.convert(text)

def word_class(text, before):
    """Inspect words ending now, including a word split across two tokens."""
    match = _HAN.search(text)
    if not match:
        return -1, ''
    ending = match.group()
    joined = before + ending
    for n in range(min(4, len(joined)), 1, -1):
        if n < len(ending) and not ending.startswith('的'):
            continue
        w = joined[-n:]
        k = meaning(w)
        if k >= 0:
            return k, w
        # Do not extract a misleading suffix from a known dictionary word.
        if k == -1 and n >= len(ending):
            return -1, ''
    return -1, ''


def word_class_is_question(word):
    return 'how' in cedict.glosses(word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, pending = '', b''
    else:
        before, pending = carry[1:]
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    decoded = decoder.decode(pending + prefix.token_bytes[-1], final=False)
    pending = decoder.getstate()[0]
    text = simplify(decoded)
    value = 0.002
    k, word = word_class(text, before)
    if k >= 0:
        value = MANNER[k][2]
        context = (before + text)[:-len(word)]
        if MANNER[k][0] == 'method' and not word_class_is_question(word):
            using = re.search(r'(以|用|通过|按照).{0,7}$', context)
            value = -0.9 if using else -0.12
        if MANNER[k][0] == 'extent':
            degree = r'[大小高低长短深近远]$'
            sized = re.search(degree, context) or re.match(degree[:-1], word)
            value = -1.2 if sized else -0.2
        if re.search(r'(能|能够|可以|可|让|使|得以)$', context):
            value *= 1.35
        elif context.endswith('的'):
            value *= 0.7
    # Size and duration phrases can be several tokens, with an optional 的.
    joined = before + text
    if text and re.search(r'[长短]的?(时间|期|途|距离)$', joined):
        value = -0.65 if joined.endswith('期') else -1.25
    elif text and re.search(
        r'[大小高低近远深广全多]的?(规模|幅度|尺度|面积|比例|距离|'
        r'额|容量|范围|深度|质量|精度|强度)$', joined
    ):
        value = -1.15
    if text in (',', '，', '、') or text.endswith('，'):
        clause = re.split(r'[,，、。.！!？?；;:\n]', before)[-1]
        han = regex.search(r'\p{Script=Han}', clause)
        if text == '、':
            value = 0.04 - 0.10 * min(1.0, len(clause) / 7)
            if _KANA.search(clause):
                value -= 0.21
        elif han or text != ',':
            value = 0.02 - 0.42 * min(1.0, len(clause) / 7)
            if _KANA.search(clause):
                value += 0.26
            frame = (r'(时|后|前|中|上|下|内|外|期间|以来|时候|'
                     r'表示|认为|说|看来)$')
            if re.search(frame, before):
                value += 0.28
            if any(introductory(before[-n:]) for n in (2, 3, 4)):
                value += 0.21
        else:
            value = -0.002
    return (doc, (before + text)[-60:], pending), float(value)

"""A partial, spelling-based surrogate for this early-layer component.

Short il/ir/ul/ur fragments followed by g or ch tend negative, as do
several related name fragments. G-prefixed identifiers tend positive.
There are smaller corrections for guild/quilt/grav and middle-dot runs.
Only the unfinished word and previous token are remembered. Unmatched
positions predict zero. Amplitudes are conservatively shrunk; these rules
do not explain every activation.
"""
import re
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()


@lru_cache(maxsize=65536)
def spelling(token):
    # Fold European alphabets together, without romanizing other scripts.
    if regex.fullmatch(r'[\p{Latin}\p{Greek}\p{Cyrillic}\p{M}\P{L}]*', token):
        return anyascii(token).lower()
    return token.lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    t = spelling(token)
    split = bool(word and t and t[0].isalpha())
    old = spelling(previous).strip() if split else ''
    short = old.isalpha() and len(old) <= 4
    liquid = short and bool(re.search(r'[iu][lr]$', old))
    full = word + t if split else t.lstrip()
    full = re.split(r'[^\w]', full)[-1][-32:]
    value = 0.0

    # Continuations of short word pieces, not arbitrary whole-word suffixes.
    if short:
        if liquid:
            if t.startswith('g'):
                value -= 2.30
            if t.startswith('ch'):
                value -= 2.00
        elif t.startswith('g'):
            if old.endswith('r'):
                value -= 0.27
            if old.endswith('l'):
                value -= 0.56
        if old.endswith('il'):
            if t.startswith('h'):
                value -= 0.62
            if t.startswith('f'):
                value -= 1.12
            if t.startswith(('ig', 'ich')):
                value -= 2.48
        if ((old == 'gl' and t[0] in 'eio')
                or (old.endswith('ig') and t.startswith('l'))):
            value -= 0.66
        if re.search(r'[iu][lr]g$', word) and t[0].isalpha():
            value -= 1.07
        if old == 'gu' and t.startswith('i'):
            value += 0.61

    # Strong fragments, distinct from merged words such as 'urgent'.
    if t.strip() == 'urg' or (split and word.endswith('u') and t == 'rg'):
        value -= 3.09
    if t.strip() in ('burg', 'burgh', 'burger'):
        value -= 1.12
    if (split and len(old) <= 5 and previous.strip()[:1].isupper()
            and t == 'rich'):
        value -= 1.95
    if split and word.startswith('guil') and t.startswith(('h', 'er')):
        value -= 3.87

    # Recognizable technical spellings and G-initialisms.
    tech = re.search(r'(?:grpc|gzip|gcp|gql|gpd|gq|glp|graalvm|nghttp)$', full)
    if tech:
        if tech[0] == 'grpc':
            value += 4.08
            if not t.endswith('grpc'):
                value += 2.02
        elif tech[0] == 'gzip':
            value += 3.49
        else:
            value += 1.82
    if full == 'guild':
        value += 1.78
    if split and full.startswith('quilt'):
        value += 3.33
    if split and re.match(r'grav.{0,3}$', full):
        value += 0.54
    if len(token.strip()) >= 2 and set(token.strip()) == {'·'}:
        value -= 0.64

    # Surface-only matches are uncertain, so use conservative amplitudes.
    return (doc, full, token), 0.65 * value

"""A short-construction detector, not a topic detector.

English 'let me/us', 'let's', first-person future auxiliaries, and repeated
phrases ('from time to time') give positive values, as does 'if so'.
Selected bare complements of place/time and article-free idioms give negatives.
Semicolon-terminated import headers and C includes form a separate positive
case. These rules approximate the strong responses, not the many small ones.
Unrecognized text gives zero; state is just a short text tail, reset at each
document boundary.
"""
import re

READS = ()

# These place nouns commonly occur without an article.
INSTITUTIONS = {'school', 'church', 'campus', 'bed', 'town'}
MOTION_OR_START = re.compile(
    r'\b(go|went|going|come|came|coming|return|returned|returning|back|'
    r'put|puts|set|sets|get|take|taken|took|bring|brought|send|sent|'
    r'down|out|me|you|him|her|us|them) to$', re.I)


def bare_complement(prior, word, history):
    """Strengths for familiar article-free English constructions."""
    if word in {'here', 'there', 'wherever'}:
        return {'from': -4.1, 'around': -3.0, 'of': -2.4,
                'to': -1.9, 'over': -1.7, 'in': -0.35}.get(prior, 0.0)
    if word == 'now':
        return {'from': -2.9, 'for': -3.2, 'by': -2.5,
                'between': -3.2, 'until': -1.0}.get(prior, 0.0)
    if word == 'then':
        return {'since': -0.55, 'by': -2.3, 'until': -0.7}.get(prior, 0.0)
    if word in {'where', 'when'} and prior in {'to', 'from', 'for'}:
        return -2.2 if word == 'where' else -1.1
    if word in {'above', 'below', 'within'}:
        return {'from': -2.0, 'to': -1.3, 'as': -0.9}.get(prior, 0.0)
    if word == 'before':
        return {'as': -1.5, 'than': -1.9, 'from': -1.3,
                'to': -0.8}.get(prior, 0.0)
    if word == 'home':
        return {'from': -2.7, 'at': -1.7, 'to': -1.4,
                'like': -1.0, 'back': -0.8}.get(prior, 0.0)
    if word == 'work':
        if prior == 'to':
            return -2.5 if MOTION_OR_START.search(history) else -0.35
        return {'at': -1.7, 'for': -1.6, 'from': -3.4,
                'after': -3.4, 'between': -2.6, 'of': -0.4}.get(prior, 0.0)
    if word in INSTITUTIONS:
        return {'to': -1.1, 'from': -1.6, 'after': -1.3,
                'at': -0.5, 'on': -0.8}.get(prior, 0.0)
    if word == 'sea':
        return -2.8 if prior in {'above', 'below'} else (-1.1 if prior == 'at' else 0.0)
    if prior in {'as', 'than'}:
        if word in {'usual', 'always'}:
            return -2.9
        if word in {'ever', 'normal'}:
            return -1.5
        if word in {'intended', 'planned'}:
            return -1.9
        if word == 'expected':
            return -0.6
        if word == 'possible':
            return 0.4
    if prior == 'for' and word in {'sure', 'once', 'later', 'free', 'nothing'}:
        return -1.1
    if prior == 'by' and word in {'design', 'definition', 'hand'}:
        return -1.0
    if prior == 'from' and word == 'scratch':
        return -2.7
    if word in {'zero', 'normal', 'death'} and prior in {'to', 'from'}:
        return -0.9
    if prior == 'of' and word == 'breath':
        return -1.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word, prior = token.strip().lower(), previous.strip().lower()
    value = 0.0
    # A word boundary prevents confusing 'now' with a suffix in another word.
    if token[:1].isspace():
        value = bare_complement(prior, word, history)
        if prior == 'let' and word in {'me', 'us'}:
            value = 1.7 if previous.strip() == 'let' else 1.95
        elif prior == 'if' and word == 'so':
            value = 1.2
        elif word == 'time':
            if history.lower().endswith('time to'):
                value = 2.9
            elif prior == 'from':
                value = 1.1
    if prior == 'let' and word in {"'s", '’s'}:
        value = 1.1
    if word in {'will', 'shall', "'ll", '’ll'} and prior in {'i', 'we'}:
        value = 1.35 if prior == 'i' else 0.85
        if previous.strip() == 'i':
            value = 0.5
        if word == 'shall':
            value = 1.65
        elif word == '’ll':
            value *= 0.8
        if prior == 'we' and previous.strip() == 'We':
            value += 0.25

    if word in {'import', 'using'} and re.search(r';\s*$', history):
        value = 2.4 if word == 'import' else 0.85
    # Keep the same locative reading in hyphenated 'work-from-home'.
    if word in {'home', '-home'}:
        if re.search(r'\bfrom-$', history, re.I):
            value = -2.7
        elif re.search(r'\bat-$', history, re.I):
            value = -1.8
    if word == 'use' and token.startswith('\t'):
        value = 0.8
    if word in {'<', '"'} and prior in {'include', '#include'}:
        value = 1.4 if word == '<' else 0.95
    return (doc, (history + token)[-100:], token), value

"""A coarse text-shape approximation, strongest at document openings.

Opening tabs, newlines and code delimiters usually receive positive values;
Arabic-script openings and empty // comment lines receive negative values.
Short Cyrillic tokens, English function-word classes and isolated vowels have
simple adjustments. Repetition of the opening token preserves opening status.
Otherwise the prediction is zero except for Arabic text/typography and labels
immediately after opening chat or PHP markers. Token-specific residuals and
most contextual variation are deliberately not modeled.
"""
import regex
import unicodedata

READS = ()
ARABIC = regex.compile(r'\p{Script=Arabic}')
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}
QUESTIONS = {'what', 'which', 'who', 'where', 'when', 'why', 'how'}


def opening_value(s):
    w = s.strip()
    if '\0' in s:
        return 6.4
    if '\n' in s or '\r' in s:
        if w == '//':  # An empty line comment differs from its opening delimiter.
            return -5.3
        return 4.8 if w.startswith('/*') else (2.4 if len(w) <= 1 else 3.5)
    if '\t' in s:
        return 3.95 if s == '\t' else 2.0
    if not w:
        return -0.5 if len(s) == 1 else 0.2
    if ARABIC.search(s):
        return -11.2
    if len(w) <= 3 and CYRILLIC.search(w):
        return 1.8 if w.isupper() else 0.85
    if w.startswith(('//', '/*', '<?')):
        return 3.1
    if len(w) > 1 and set(w) == {'·'}:
        return 2.25
    word = w.lower()
    if word == 'i':
        return 3.5
    if word == 'we':
        return 2.2
    if word == 'you':
        return 0.9
    if word in {'he', 'she'}:
        return 1.4
    if word in BE:
        return 0.7
    if word == 'a':
        return 0.15
    if word in QUESTIONS:
        return -1.5
    if len(w) == 1 and word in 'aeiou':
        return 1.5
    if w.isdecimal():
        return 0.15
    if w.isascii() and w.isalpha() and len(w) > 3:
        return -0.3
    return -0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    opening = (carry is None or carry[0] != doc or
               (carry[2] and carry[1] == s))
    if opening:
        value = opening_value(s)
    else:
        w = s.strip()
        if carry[2] and carry[1] == '<|im_start|>':
            value = 0.45 if w == 'user' else 1.4 if w in {
                'system', 'assistant'} else 0.0
        elif carry[2] and carry[1].strip() == '<?' and w == 'php':
            value = 1.25
        elif w == '،':
            value = 1.85
        elif w == '؛':
            value = 3.8
        elif w == '؟':
            value = 0.5
        elif w and set(w) == {'ـ'}:
            value = 1.4
        elif any('ARABIC' in unicodedata.name(c, '') and
                 unicodedata.category(c) == 'Mn' for c in w):
            value = 0.4
        elif ARABIC.search(s):
            value = (0.05 if len(w) <= 2 or not s.startswith(' ')
                     else 0.28 if len(w) == 3 else 0.16)
        else:
            value = 0.0
    return (doc, s, opening), value

programs.haiku:
"""Component layers.1.mlp.down_proj:2803 (layer-1 MLP output direction).

What it does, in plain terms: this component is nearly silent inside running text,
but it fires strongly on the first token of each document (or of each packed row,
where a document was cut). There the sign depends on what kind of text starts:
  * a line break or tab (end of a code line, blank line) -> strongly positive;
  * Cyrillic letters -> positive;
  * Arabic-script letters -> strongly negative (rare, but the largest values);
  * code-like punctuation (; ) } ] / * # " ...) -> mildly positive;
  * ordinary words, digits, CJK -> about zero; a word with a leading space (a
    mid-sentence fragment, e.g. " to") is slightly negative.
Mid-document it fires on Arabic-script text: the Arabic comma and semicolon (، ؛)
give a clear positive value, and other Arabic letters a small one.

The program is stateless: it only reads the newest token and whether it starts a
document (position 0 of the row, or the document id changed).
"""
import unicodedata

READS = ()

ARABIC_COMMAS = ("،", "؛")          # Arabic comma, Arabic semicolon
CODE_PUNCT = set(";{}()[]<>/*#\"'=_|\\")


def _names(s):
    return [unicodedata.name(c, "") for c in s]


def _script(s, word):
    return any(word in n for n in _names(s))


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    starts_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_doc:
        if _script(s, "ARABIC"):
            return None, -9.0
        if any(c in s for c in "\n\r\t"):
            return None, 2.7
        if _script(s, "CYRILLIC"):
            return None, 1.1
        if s.strip() and not any(c.isalnum() for c in s):
            return None, 0.4 if any(c in CODE_PUNCT for c in s) else 0.1
        if s[:1] == " " and s[1:].isalpha():
            return None, -0.2
        return None, 0.0
    if s in ARABIC_COMMAS:
        return None, 1.9
    if _script(s, "ARABIC"):
        return None, 0.09
    return None, 0.0

programs.sol:
"""Recognize the written stem 'net', especially as a separate subword.

Network words, names ending in Net, programming namespaces, and several
non-Latin spellings give negative contributions. A split n|et is stronger
than the same letters buried in a whole word. Ordinary magnet/planet
stems are weaker. Other tokens return zero. Keep a short byte tail for
splits and namespace context, resetting it at each document boundary.
"""
import re

READS = ()


def response(before, token):
    s = token.lower()
    previous = before.lower()
    joined = previous + s

    # Loanwords for 'net', and the Chinese character meaning net.
    if 'ネット' in s:
        return -6.3 if s == 'ネット' else -1.4
    if 'ネット' in joined[-len(s)-3:] and 'ット' in s:
        return -8.5
    if '넷' in s:
        return -6.0 if s == '넷' else -1.5
    if s in ('网', '網'):
        if previous.endswith(('因特', '以太')):
            return -4.2
        return -2.5 if s == '網' else -1.3
    if any(w in s for w in ('网络', '網路', '網絡', '网上')):
        return -1.5
    if s in ('网友', '網友', '互联网'):
        return -0.5

    # Dotted namespace names are much stronger than web-domain endings.
    if s == '.net':
        if previous.endswith('java'):
            return -11.0 if previous.endswith('-djava') else -18.0
        if previous.endswith(('android', 'system')):
            return -14.0
        return -3.8
    if s.lstrip() == 'net':
        if re.search(r'(import|package)\s*$', previous):
            return -10.0
        if previous.endswith(('link', 'listener')):
            return -7.0
        if not s[0].isspace():
            if previous.endswith('"'):
                return -9.5
            if token == 'net' and re.search(r'(ord|öff|gön)$', previous):
                return -0.5
            if re.search(r'(mag|electromag)$', previous):
                return -0.5
            if token == 'NET' and previous.endswith('.'):
                return -1.5
            return -5.5 if token[0].isupper() else -4.5
        if re.search(r'[;{}=]|::|\b(let|struct)\b', previous[-60:]):
            return -6.0
        return -3.5 if token.strip()[0].isupper() else -3.0
    if re.fullmatch(r'[-/"(]net', s):
        return -9.0 if s[0] in '-"' else -5.0
    if s == '_net':
        return -3.0
    word = s.strip(' ./_-\t\n')
    if word.startswith('network'):
        if len(s) != len(word) and not s[0].isspace():
            return -2.8
        if s[0].isspace():
            return -0.7 if word.endswith('s') else -1.0
        return -1.8
    if word in ('internet', 'ethernet', 'subnet', 'inet'):
        if word != 'internet':
            return -4.5 if word == 'inet' else -3.0
        return -1.7 if s[0].isspace() else -2.9
    if re.fullmatch(r'net[stz]|nett', word):
        return -4.3 if s[0].isspace() else -3.5
    if re.fullmatch(r'[ieo]net|ernet', s):
        return -4.3

    # A separately tokenized final t, or suffixes of net-ting / Net-ze.
    if previous.endswith('ne') and s in ('t', '-t'):
        return -4.5
    if previous.endswith('net') and s and s[0].isalpha():
        return -4.5 if s.startswith(('t', 'z')) else -1.0

    # n followed by an et-like suffix, including accented Latin spelling.
    plain = s.replace('é', 'e')
    if previous.endswith('n') and (plain.startswith('et') or s.startswith('ät')):
        if previous.endswith('magn') or (previous.endswith('plan')
                                        and plain in ('et', 'ets')):
            return -1.5
        if plain in ('et', 'ett'):
            return -11.0 if token.isupper() else -7.7
        if plain.startswith(('etic', 'etics')):
            return -0.8
        if plain.startswith('eth'):
            return -2.0
        return -4.0 if len(plain) <= 4 else -1.5
    if previous.endswith('н') and s.startswith('ет'):
        if s.startswith(('ется', 'етесь')):
            return 0.0
        return -1.5 if previous.endswith('план') else -3.5
    if 'нет' in s:
        return -2.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else b''
    current = prefix.token_bytes[-1]
    text = current.decode('utf-8', 'replace')
    context = before
    # Join only an unfinished UTF-8 character, not a previous complete one.
    if current and 128 <= current[0] < 192:
        start = len(before) - 1
        while start > 0 and 128 <= before[start] < 192:
            start -= 1
        ending = before[start:]
        if ending and ending[0] >= 192:
            text = (ending + current).decode('utf-8', 'replace')
            context = before[:start]
    value = response(context.decode('utf-8', 'replace'), text)
    return (doc, (before + current)[-96:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:2804: a "net" detector.

This unit goes negative when the text spells the word "net" as a piece of a word:
  - ".net" (java.net, .NET) about -8; "net", "Net", " net", "nets", "inet", "subnet" and
    katakana ネット about -5. Inside code imports (`import java.net`, `import net.minecraft`)
    the value is about 1.5 times stronger.
  - a token starting with "et" that follows text ending in "n" (INTERN|ET, garn|et, Schienen|etz):
    about -6 for "et", about -3 for other "et..." pieces.
  - "NET" in capitals about -2.3; "network", "internet" and friends about -1.3;
    网, 網, нет, интернет and similar non-Latin words about -1.6.
Everywhere else it predicts 0, since words that merely contain the letters n-e-t
(planet, cabinet, magnetic, genetic) do not fire. Only the current token and the
last few characters of text are read.
"""

READS = ()

NET_WORD = {"net", "nets", "inet", "subnet", "ネット"}
NETWORK_WORD = {"network", "networks", "networking", "internet", "internets", "インターネット"}
NON_LATIN = {"网": -1.6, "網": -1.6, "网络": -1.3, "нет": -1.6, "интернет": -2.0, "сеть": -1.3, "сети": -1.3}
CODE = ("import", "java", "android")


def step(carry, prefix, upstream):
    tail, doc = carry if carry is not None else ("", None)
    if prefix.document_ids[-1] != doc:
        tail = ""
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    word = "".join(c for c in tok.lower() if c.isalpha())
    value = 0.0
    if tok in (".net", ".NET"):
        value = -8.0
    elif word in NET_WORD:
        value = -5.0
    elif tok == "NET":
        value = -2.3
    elif tok.lower().startswith("et") and not tok.startswith(" ") and tail.endswith("n"):
        value = -6.0 if tok in ("et", "ET") else -3.0
    elif tok == "ット" and tail[-1:] in ("ネ", "�"):
        value = -5.0
    elif word in NETWORK_WORD:
        value = -1.3
    elif word in NON_LATIN:
        value = NON_LATIN[word]
    if value <= -4 and any(c in tail for c in CODE):
        value *= 1.5
    tail = (tail + tok.lower())[-60:]
    return (tail, doc), value

programs.sol:
"""Approximate the component's conditional-wish response.

'Would like/love' (also 'I'd') is strongly positive, including intervening
adverbs. 'To' carries a smaller response after these verbs and after positive
feeling adjectives. Ordinary, nonconditional 'like/love' is weakly negative.
A blank // comment at a document's beginning is another positive trigger.
Other spelling-fragment responses are left unexplained.
"""
import wordnet

READS = ()
CONDITIONAL = {'would', "'d", '’d'}
WEAKER = {'may', 'might', 'could', 'should', 'will'}
FEELINGS = {'glad', 'pleased', 'delighted', 'thrilled', 'proud', 'fortunate'}


def modal_before(history):
    """Look through at most three adverbs or perfect auxiliaries."""
    for distance, word in enumerate(reversed(history[-4:])):
        if word in CONDITIONAL or word in WEAKER:
            return word, distance
        if word not in {'have', 'of'} and (
            not word.isalpha() or 'adverb' not in wordnet.parts_of_speech(word)
        ):
            break
    return '', 0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
