@lru_cache(maxsize=32768)
def lexical(text):
    t = text.strip()
    if not t:
        return 0.0
    if len(t) >= 2 and set(t) == {'·'}:
        return -1.62
    c = t[0]
    if 'CJK UNIFIED' in ud.name(c, ''):
        sound = lazy_pinyin(c)[0]
        gloss = '; '.join(cedict.glosses(t)).lower()
        head = '; '.join(cedict.glosses(c)).lower()
        if sound == 'you':
            if 'especially' in gloss or 'particularly' in gloss:
                return 9.0 / len(t) ** 0.5
            if 'still' in gloss or 'as if' in gloss:
                return 9.3 / len(t) ** 0.5
            if len(t) == 1 and ('superior' in head or 'worry' in head):
                return 2.5
            return 0.12
        if sound == 'ou' and 'europe' in head:
            return 3.0 / len(t) ** 1.6
        if sound == 'ya' and 'asia' in head:
            return 2.0 / len(t) ** 1.6
        if 'especially' in gloss or 'particularly' in gloss:
            return 0.5
