"""A small approximation of the component's layout-whitespace response.

Predict zero for ordinary text, with a small offset at document starts.
Multi-column padding after newlines gets a negative response, especially when
the preceding token is itself whitespace. Space-padded blank lines also get a
negative response that grows with the preceding whitespace run, up to a cap.
Token-specific lexical effects and finer layout distinctions are omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, position, white_run = '', 0, 0
    else:
        _, previous, position, white_run = carry
    value = 0.0
    if position == 0 and not token.startswith('<|'):
        value = 0.24
    elif token.isspace():
        # Estimate indentation width with four columns per tab.
        padding = token.count(' ') + 4 * token.count('\t')
        if padding >= 2 and '\n' in previous:
            if previous.isspace():
                value = -min(1.7, 0.35 + 0.1 * padding)
            elif padding % 4 == 0:
                value = -0.3
        if padding and '\n' in token:
            value = -min(4.5, 0.12 * padding + 0.4 * white_run)
    new_run = white_run + 1 if token.isspace() else 0
    return (doc, token, position + 1, new_run), value

