"""Layer-1 MLP component 2814 (down_proj): an indentation-run detector."""

READS = ()


def _blank(s):
    return len(s) > 0 and s.strip(" \t\r\n") == ""


def step(carry, prefix, upstream):
    run = carry or 0  # whitespace-only lines ending just before this token
    s = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    value = 0.0
    if len(s) >= 2 and set(s) == {"·"}:
        value = 1.4
    elif _blank(s) and same_doc and prefix.token_strings[-2].endswith("\n") and run > 0:
        n = len(s)
        if n % 2 == 0:
            if n >= 16:
                value = -2.5 if run == 1 else -3.5
            elif n >= 8:
                value = -1.5
    if _blank(s) and s.endswith("\n"):
        run += 1
    else:
        run = 0
    return run, value

programs.sol:
"""Selection from a group: 'one/which/some of', and 'is among'.

A linking preposition gets a large positive value when it follows a
selector, not in ordinary possessive 'of' phrases. The following article
gets a smaller echo. Equivalent partitives in several languages are
recognized too. A few number constructions and singular time units
account for smaller responses. Only a short text suffix is remembered.
"""
import re
import inflect

READS = ()
SELECTORS = {
    'one': 10.8, 'which': 10.8, 'either': 8.8, 'neither': 7.2,
    'any': 7.0, 'none': 6.5, 'each': 6.7, 'several': 5.8,
    'some': 4.7, 'many': 4.9, 'few': 4.1, 'both': 3.0,
    'couple': 1.7, 'first': 2.6, 'last': 3.2, 'another': 7.0,
}
_engine = inflect.engine()
CARDINALS = {_engine.number_to_words(n) for n in range(2, 21)}
BE = set('am is are was were be been being'.split())
ROMANCE_ONE = set('un une uno una um uma'.split())
ROMANCE_SELECTORS = set(
    'alguno alguna algunos algunas algumas alcuni quelques-uns '
    'qual ciascuno qualcuno aucun'.split()
)
GERMAN_ONE = set('ein eine einer eines einem einen eins'.split())
RUSSIAN_ONE = set('один одна одно одни одного одной одном одним одну'.split())
RUSSIAN_SOME = set('каждый каждого каждую любой некоторые многие многих'.split())
TIME_UNITS = set('year month week day hour minute second'.split())
WORD = re.compile(r"[\w'’\-]+")


def last_word(text):
    text = text.rstrip()
    match = WORD.match(text[::-1])
    if not match:
        return '', ''
    word = match[0][::-1].strip("'’-")
    return word, text[:-len(match[0])]


def selector(word):
    lower = word.lower()
    value = SELECTORS.get(lower, 5.3 if lower in CARDINALS else 0.0)
    if word[:1].isupper():
        if lower in {'one', 'which', 'none'}:
            value += 1.2
        elif lower in {'some', 'any'}:
            value -= 0.9
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', 0.0)
    _, history, link = carry
    text = history.decode('utf-8', 'ignore')
    previous, rest = last_word(text)
    before, _ = last_word(rest)
    prev, earlier = previous.lower(), before.lower()
    raw = prefix.token_bytes[-1].decode('utf-8', 'ignore')
    word = raw.strip().lower()
    # A token fragment inside 'Cordileone' is not the selector 'one'.
    boundary = not text or not text[-1].isalnum() or raw[:1].isspace()
    value = 0.0
    if boundary or word == '-of':
        strength = selector(previous)
        if word in {'of', '-of'}:
            value = strength
            if prev == 'one':
                if earlier in {'each', 'every', 'any', 'the', 'last'}:
                    value = 4.8
                elif earlier in {'which', 'not', 'least', 'only', 'just'}:
                    value = 8.0
                elif earlier in {'is', 'are', 'was', 'were', 'as'}:
                    value = 11.6
            elif prev.isdecimal():
                value = 1.2
            elif prev == 'out':
                value = 5.0 if selector(before) or earlier.isdecimal() else 0.2
            elif prev == 'more' and earlier == 'or':
                left, _ = last_word(rest.rstrip()[:-len(before)])
                value = 6.5 if left.lower() in CARDINALS | {'one'} else 0.0
            if prev in CARDINALS | {'one'}:
                if earlier in {'part', 'chapter', 'section', 'volume', 'episode', 'number'}:
                    value = 0.2
                elif prev in CARDINALS and earlier in {'is', 'are', 'was', 'were'}:
                    value += 2.5
            if word == '-of':
                value *= 0.45
        elif word in {'among', 'amongst'}:
            value = 8.0 if prev in BE else 0.9
            if prev == 'and':
                value = 3.3
        elif word in {'de', 'des', 'dos', 'das', 'dei', 'delle', 'degli', 'di'}:
            p = prev.removeprefix("l'").removeprefix('l’')
            if p in ROMANCE_ONE:
                value = 6.5 if p == 'un' and word == 'de' else 12.0
                if word == 'di':
                    value = 7.5
                if p == 'um' and word in {'des', 'das', 'di'}:
                    value = 0.0
            elif p in ROMANCE_SELECTORS:
                value = 7.5
        elif word in {'der', 'von'} and prev in GERMAN_ONE:
            value = 5.0 if prev in {'ein', 'eins'} else 9.0
        elif word == 'von' and prev == 'zwei':
            value = 6.0
        elif word == 'van' and prev in {'een', 'één'}:
            value = 12.0
        elif word == 'из':
            if prev in RUSSIAN_ONE:
                value = 6.0 if prev == 'одно' else 11.8
            elif prev in RUSSIAN_SOME:
                value = 4.0 if prev in {'многие', 'многих'} else 6.8
        elif word == 'z' and prev in {'jeden', 'jedna', 'jedną', 'jednym', 'każdy'}:
            value = 9.0 if prev == 'jeden' else 7.0
        elif word == 'trong' and prev == 'một':
            value = 15.0
        elif word == 'بعض':
            value = 5.0
        elif word == 'من' and prev in {'واحد', 'كل', 'أحد'}:
            value = 4.5

        if prev == 'of' and word == 'the':
            gain = 0.4 if earlier == 'one' else 0.28
            if earlier in {'which', 'either'}:
                gain = 0.14
            elif earlier in CARDINALS:
                gain = 0.47
            value = gain * link
        elif prev in {'among', 'amongst'} and word == 'the':
            value = 0.2 + 0.14 * link
        elif prev == 'de' and word in {'los', 'las'}:
            value = 0.57 * link
        if word in {'or', 'out'} and prev in CARDINALS | {'one'}:
            value = 2.5 if word == 'or' else 4.5
        if prev == 'or' and word == 'more' and earlier in CARDINALS | {'one'}:
            value = 2.7
        if prev == 'one' and word.lstrip('-') in TIME_UNITS:
            value = -2.1 if word == 'year' else (-0.5 if word == 'day' else -1.5)
        elif prev == 'one' and word in {'big', 'large', 'main', 'last', 'other'}:
            value = -1.3
    if prev == 'one' and word in {"'s", '’s'}:
        value = -1.3
    updated = (history + prefix.token_bytes[-1])[-96:]
    complete, _ = last_word(updated.decode('utf-8', 'ignore'))
    if raw.strip() and complete in {'احد', 'أحد', 'لأحد', 'إحدى'}:
        value = 8.0
    next_link = link if raw.isspace() else value
    return (doc, updated, next_link), float(value)
